import sys, re
import xml.etree.ElementTree as ET

def text_of(el):
    return re.sub(r'\s+', ' ', ''.join(el.itertext())).strip()

def main(path, out):
    tree = ET.parse(path)
    root = tree.getroot()
    lines = []
    front = root.find('front')
    if front is not None:
        for t in front.iter('article-title'):
            lines.append('TITLE: ' + text_of(t))
        for ab in front.iter('abstract'):
            lines.append('ABSTRACT: ' + text_of(ab))
        for kw in front.iter('kwd'):
            lines.append('KWD: ' + text_of(kw))
        for hist in front.iter('date'):
            lines.append('DATE ' + str(hist.get('date-type')) + ': ' + text_of(hist))
        for pd in front.iter('pub-date'):
            lines.append('PUBDATE ' + str(pd.get('pub-type') or pd.get('date-type')) + ': ' + text_of(pd))
        for aid in front.iter('article-id'):
            lines.append('ARTICLE-ID ' + str(aid.get('pub-id-type')) + ': ' + text_of(aid))
        for fn in front.iter('fn'):
            lines.append('FRONT-FN: ' + text_of(fn))
    body = root.find('body')
    def walk(el, depth=0):
        tag = el.tag
        if tag == 'sec':
            title = el.find('title')
            if title is not None:
                lines.append('\n' + '#' * (depth + 1) + ' ' + text_of(title))
            for ch in el:
                if ch.tag == 'title':
                    continue
                walk(ch, depth + 1)
        elif tag == 'p':
            lines.append('P: ' + text_of(el))
        elif tag in ('fig', 'table-wrap'):
            lab = el.find('label')
            cap = el.find('caption')
            lines.append('[' + tag.upper() + '] ' + (text_of(lab) if lab is not None else '') + ' ' + (text_of(cap) if cap is not None else ''))
            if tag == 'table-wrap':
                for tr in el.iter('tr'):
                    cells = [text_of(c) for c in tr if c.tag in ('td', 'th')]
                    lines.append('  ROW: ' + ' | '.join(cells))
                for fn in el.iter('fn'):
                    lines.append('  TABLE-FN: ' + text_of(fn))
        elif tag in ('list',):
            for li in el.iter('list-item'):
                lines.append('LI: ' + text_of(li))
        else:
            for ch in el:
                walk(ch, depth)
    if body is not None:
        for ch in body:
            walk(ch, 0)
    back = root.find('back')
    if back is not None:
        for sec in back:
            if sec.tag == 'ref-list':
                for i, ref in enumerate(sec.iter('ref')):
                    lines.append('REF ' + str(ref.get('id')) + ': ' + text_of(ref))
            else:
                lines.append('BACK-' + sec.tag + ': ' + text_of(sec))
    with open(out, 'w') as f:
        f.write('\n'.join(lines))

main(sys.argv[1], sys.argv[2])
