/**
 * Kidney markers of KDM v2.2: creatinine, after the creatine offset, in both
 * versions. Cystatin C and the laboratory's creatinine-based eGFR are stored
 * and shown but never used (`KDM_UNUSED_MARKERS`), and nothing stands in for
 * creatinine at the gate.
 *
 * Run: `npx vitest run src/lib/biomarkers/biological-age-kdm.kidney.test.ts`
 */
import { describe, expect, it } from "vitest";
import {
  KDM_UNUSED_MARKERS,
  computeComprehensiveBA,
  computeReferenceBA,
  countBasePanelMarkers,
  passesKdmGate,
  resolveKdmParams,
  type KdmPatientContext,
  type Sex,
} from "./biological-age-kdm";
import type { BiomarkerInput } from "./longevity-score";

// Ten base-panel markers, as the Base Panel supplies them (typical man of 45 of scripts/kdm_explain_panels.ts).
const BASE: BiomarkerInput[] = Object.entries({
  albumin: 44, creatinine: 1.0, bun: 15, uric_acid: 6.0, alp: 72, ggt: 32,
  total_cholesterol: 205, hdl_cholesterol: 47, triglycerides: 140, hs_crp: 1.8,
}).map(([code, value]) => ({ code, value }));
const add = (extra: Record<string, number>) => [...BASE, ...Object.entries(extra).map(([code, value]) => ({ code, value }))];
const CREATINE: KdmPatientContext = { supplements: [{ key: "creatine", dose: "5g" }] };
const TIERS = [["Reference", computeReferenceBA], ["Comprehensive", computeComprehensiveBA]] as const;

describe("kidney markers — creatinine only, in both versions", () => {
  it("cystatin C and the laboratory's eGFR are unused and get no parameters", () => {
    expect([...KDM_UNUSED_MARKERS].sort()).toEqual(["Cistatina C", "TFGe (basada en Creatinina)"]);
    for (const restrict of [true, false]) {
      const { params } = resolveKdmParams({ Creatinina: 1, "Cistatina C": 0.9, "TFGe (basada en Creatinina)": 95 }, "male", restrict);
      expect(Object.keys(params)).toEqual(["Creatinina"]);
    }
  });

  for (const [tier, f] of TIERS) {
    it(`${tier}: the same BA with or without cystatin C and lab eGFR, whatever their values and units`, () => {
      for (const sex of ["male", "female"] as Sex[]) {
        for (const ctx of [null, CREATINE]) {
          const base = f(BASE, sex, 45, ctx)!;
          expect(base.used_markers).toContain("Creatinina");
          for (const extra of [
            { cystatin_c: 0.85 }, { cystatin_c: 1.5 }, { cystatin_c: 63.75 }, { egfr_creatinine_based: 70 },
            { EGFR: 95, egfr: 95 }, { cystatin_c: 0.85, egfr_creatinine_based: 110 },
          ]) {
            const r = f(add(extra), sex, 45, ctx)!;
            expect(r.BA).toBe(base.BA);
            expect(r.used_markers).toEqual(base.used_markers);
          }
        }
      }
    });

    it(`${tier}: applies the creatine offset to creatinine when cystatin C is present`, () => {
      const onCreatine = f(add({ cystatin_c: 0.85 }), "male", 45, CREATINE)!;
      const off = f(add({ cystatin_c: 0.85 }), "male", 45, null)!;
      const lowered = f(BASE.map((v) => (v.code === "creatinine" ? { ...v, value: 1.0 - 0.175 } : v)), "male", 45, null)!;
      expect(onCreatine.BA).toBeLessThan(off.BA);
      expect(onCreatine.BA).toBeCloseTo(lowered.BA, 10);
    });

    it(`${tier}: cystatin C (or lab eGFR) without creatinine gives no BA`, () => {
      const noCreatinine = add({ cystatin_c: 0.85 }).filter((v) => v.code !== "creatinine");
      expect(f(noCreatinine, "male", 45)).toBeNull();
      expect(f([...noCreatinine, { code: "egfr_creatinine_based", value: 95 }], "male", 45)).toBeNull();
    });
  }

  it("the gate requires creatinine and counts only base-panel markers", () => {
    const inputs: Record<string, number> = {
      Albúmina: 4.4, "Cistatina C": 0.85, "BUN (Nitrógeno Ureico en Sangre)": 14, "Ácido Úrico": 5.2,
      "Colesterol Total": 180, "Colesterol HDL": 55, Triglicéridos: 90, "PCR de Alta Sensibilidad (hs-PCR)": 0.7,
      "ALP (Fosfatasa Alcalina)": 70,
    };
    expect(countBasePanelMarkers(inputs)).toBe(8);
    expect(passesKdmGate(inputs)).toBe(false);
    expect(countBasePanelMarkers({ ...inputs, Creatinina: 0.9 })).toBe(9);
    expect(passesKdmGate({ ...inputs, Creatinina: 0.9 })).toBe(true);
  });
});
