import sys, html
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out=[]; self.skip=0; self.cell=None; self.row=None; self.intable=0
    def handle_starttag(self, tag, attrs):
        if tag in ('script','style','noscript'): self.skip+=1
        if tag=='table': self.intable+=1; self.out.append("\n[TABLE]\n")
        if tag=='tr': self.row=[]
        if tag in ('td','th'): self.cell=[]
        if tag in ('p','div','br','h1','h2','h3','h4','li','caption') and self.cell is None: self.out.append("\n")
        if tag=='a':
            for k,v in attrs:
                if k=='href' and v and ('.pdf' in v.lower() or 'download' in v.lower() or 'mmc' in v.lower() or 'supl' in v.lower()):
                    self.out.append(f" [LINK:{v}] ")
    def handle_endtag(self, tag):
        if tag in ('script','style','noscript'): self.skip=max(0,self.skip-1)
        if tag in ('td','th') and self.cell is not None and self.row is not None:
            self.row.append(" ".join("".join(self.cell).split())); self.cell=None
        if tag=='tr' and self.row is not None:
            self.out.append(" | ".join(self.row)+"\n"); self.row=None
        if tag=='table': self.intable-=1; self.out.append("[/TABLE]\n")
    def handle_data(self, data):
        if self.skip: return
        if self.cell is not None: self.cell.append(data)
        else: self.out.append(data)
p=P(); p.feed(open(sys.argv[1],encoding='utf-8',errors='replace').read())
t="".join(p.out)
import re
t=re.sub(r'[ \t]+',' ',t); t=re.sub(r'\n\s*\n+','\n',t)
print(t)
EOF
