print('version 3 creatinine weight per ln unit', round(W, 4), 'floors', FLOOR)

def lab_slope(sex):
    den = 0.0
    for mk in V.BASE10:
        k, q, s, log = V.params(mk, sex, 'deployed', None)
        den += (k / s) ** 2
    k, q, s, log = V.params(V.CRE, sex, 'deployed', None)
    assert not log
