// Applies one mutation (file, from, to) to the scratch copy, runs the biomarker tests, restores the file.
import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";
const ROOT = "/tmp/claude-0/-home-user-eva-health/4e1a7523-c199-547a-904f-d87e53286958/scratchpad/review3/review-dataflow/repo";
const mutations = JSON.parse(readFileSync(process.argv[2], "utf8"));
for (const m of mutations) {
  const path = `${ROOT}/${m.file}`;
  const orig = readFileSync(path, "utf8");
  const count = orig.split(m.from).length - 1;
  if (count !== (m.count ?? 1)) { console.log(`[${m.id}] SKIP: 'from' found ${count} times`); continue; }
  writeFileSync(path, orig.split(m.from).join(m.to));
  let out = "";
  try {
    out = execSync(`node_modules/.bin/vitest run ${m.tests ?? "src/lib/biomarkers"} 2>&1`, { cwd: ROOT, encoding: "utf8", timeout: 600000 });
  } catch (e) { out = e.stdout?.toString() ?? String(e); }
  writeFileSync(path, orig);
  const summary = out.split("\n").filter((l) => /Test Files|Tests /.test(l)).join(" | ");
  const failed = out.split("\n").filter((l) => /^\s*(FAIL|×)/.test(l)).slice(0, 6).join("\n    ");
  console.log(`[${m.id}] ${summary}\n    ${failed}`);
}
