    const upd = argsOf(c, "update");
    if (upd) { updates.push({ table: c.table, data: upd[0] }); return { data: null }; }
    if (c.ops.some((o) => o.op === "upsert")) return { data: null };
    if (c.table === "profiles") return { data: { sex: "male", date_of_birth: "1981-01-01" } };
