      const idEq = argsOf(c, "eq", "id")?.[1];
      if (idEq) return { data: labs.find((l) => l.id === idEq) ?? null };
      const statusEq = argsOf(c, "eq", "status")?.[1];
      let out = labs.filter((l) => !statusEq || l.status === statusEq);
      const gte = argsOf(c, "gte", "collection_date")?.[1] as string | undefined;
      if (gte) out = out.filter((l) => l.collection_date >= gte);
      out = [...out].sort((a, b) => b.collection_date.localeCompare(a.collection_date));
      if (c.ops.some((o) => o.op === "maybeSingle")) return { data: out[0] ?? null };
      return { data: out };
    }
    if (c.table === "biomarker_values") {
      const inIds = argsOf(c, "in")?.[1] as string[] | undefined;
      const eqLab = argsOf(c, "eq", "lab_result_id")?.[1] as string | undefined;
      const ids = inIds ?? (eqLab ? [eqLab] : []);
      return { data: ids.flatMap((id) => Object.entries(BASE).map(([k, v]) => ({ lab_result_id: id, biomarker_key: k, value: v, zone: "optimal", unit: null }))) };
