      const uid = argsOf(c, "eq", "user_id")?.[1];
      const idEq = argsOf(c, "eq", "id")?.[1];
      const inIds = argsOf(c, "in")?.[1] as string[] | undefined;
      if (inIds) return { data: versions.filter((v) => inIds.includes(v.id) && v.user_id === uid) };
      if (idEq) return { data: versions.find((v) => v.id === idEq && v.user_id === uid) ?? null };
      const mine = versions.filter((v) => v.user_id === uid).sort((a, b) => b.version_number - a.version_number);
      return { data: mine[0] ?? null };
