/**
 * Reproduction: the dashboard's rolling average applies the creatinine plausibility range to the AVERAGED,
 * creatine-ADJUSTED creatinine, not to each lab's measured value as processing does.
 */
import { describe, expect, it, vi } from "vitest";
import { fakeSupabase, ops, type FakeCall, type FakeResponse } from "@/lib/testing/fake-supabase";
import { computeComprehensiveBA, computeReferenceBA } from "@/lib/biomarkers/biological-age-kdm";
import { computeRollingAverageBA } from "@/lib/biomarkers/rolling-average-ba";

vi.mock("@/lib/supabase/server", () => ({ createClient: async () => { throw new Error("no"); } }));

const BASE: Record<string, number> = {
  albumin: 44, creatinine: 1.0, bun: 15, uric_acid: 6, alp: 72, ggt: 32, total_cholesterol: 205, hdl_cholesterol: 47,
  triglycerides: 140, hs_crp: 1.8, apolipoprotein_b_apob: 105, alt: 30, fructosamine: 200,
};
const inputs = (v: Record<string, number>) => Object.entries(v).map(([code, value]) => ({ code, value }));
const AGE = 45;
const DOB = `${new Date().getFullYear() - AGE}-01-01`;
const daysAgo = (n: number) => new Date(Date.now() - n * 86_400_000).toISOString().slice(0, 10);

function db(labCreatinines: number[], supplements: unknown[] = []) {
  const labs = labCreatinines.map((_, i) => ({
    id: `lab-${i}`, collection_date: daysAgo(10 + 30 * i), created_at: `${daysAgo(9 + 30 * i)}T10:00:00Z`, patient_context_version_id: "v1",
  }));
  const rows = labs.flatMap((l, i) =>
    Object.entries({ ...BASE, creatinine: labCreatinines[i] }).map(([biomarker_key, value]) => ({ lab_result_id: l.id, biomarker_key, value })),
  );
  const respond = (c: FakeCall): FakeResponse => {
    if (c.table === "profiles" && ops(c).startsWith("select")) return { data: { sex: "male", date_of_birth: DOB } };
    if (c.table === "lab_results") return { data: ops(c).endsWith("maybeSingle") ? labs[0] : labs };
    if (c.table === "biomarker_values") return { data: rows };
    if (c.table === "patient_context_versions") return { data: [{ id: "v1", version_number: 1, created_at: "2020-01-01T00:00:00Z", supplements }] };
    return { data: null };
  };
  return fakeSupabase(respond).client;
}

describe("rolling average vs per-lab plausibility", () => {
  it("a lab whose creatinine is implausible (0.09 mg/dL) gives no per-lab BA, yet feeds the dashboard figure", async () => {
    // Per lab (processing): no BA for the implausible lab.
    expect(computeReferenceBA(inputs({ ...BASE, creatinine: 0.09 }), "male", AGE, { supplements: null })).toBeNull();
    const r = await computeRollingAverageBA("u1", db([1.0, 0.09]));
    const fromAverage = computeComprehensiveBA(inputs({ ...BASE, creatinine: (1.0 + 0.09) / 2 }), "male", AGE, { supplements: null })!.BA;
    const goodLabOnly = computeComprehensiveBA(inputs(BASE), "male", AGE, { supplements: null })!.BA;
    console.log({ dashboard: r?.ba, fromAveragedCreatinine0545: fromAverage, goodLabOnly });
    // Expected: the implausible value never reaches the dashboard figure.
    expect(r?.ba).not.toBeCloseTo(fromAverage, 6);
  });

  it("single lab, measured 16 mg/dL (implausible) with creatine 5 g/day: no lab-page BA, but a dashboard BA", async () => {
    const CREATINE_5G = [{ key: "creatine", dose: "5 g" }];
    expect(computeReferenceBA(inputs({ ...BASE, creatinine: 16 }), "male", AGE, { supplements: CREATINE_5G })).toBeNull();
    const r = await computeRollingAverageBA("u1", db([16], CREATINE_5G));
    console.log({ dashboardWithMeasured16: r?.ba });
    expect(r).toBeNull();
  });

  it("single lab, measured 0.2 mg/dL (plausible) with creatine 5 g/day: a lab-page BA, but no dashboard BA", async () => {
    const CREATINE_5G = [{ key: "creatine", dose: "5 g" }];
    expect(computeReferenceBA(inputs({ ...BASE, creatinine: 0.2 }), "male", AGE, { supplements: CREATINE_5G })).not.toBeNull();
    const r = await computeRollingAverageBA("u1", db([0.2], CREATINE_5G));
    console.log({ dashboardWithMeasured02: r?.ba ?? null });
    expect(r).not.toBeNull();
  });
});
