  `(?:\\/|(?<![${LETTER}])(?:a\\s+la|a|al|por|per|cada|each|every))\\s*(?:la\\s+)?(?:semana|week)(?![${LETTER}])|(?<![${LETTER}])(?:semanal(?:es)?|weekly)(?![${LETTER}])`,
