/** A count's value: a number word, else the number. */
function readCount(token: string): number {
  return COUNT_WORDS[token] ?? readNumber(token, null);
}

/** A value in grams, or null when the unit is not a mass. */
function grams(value: number, unit: string | null): number | null {
  const perUnit = unit === null ? undefined : GRAMS_PER_UNIT[unit];
  return perUnit === undefined || !Number.isFinite(value) ? null : value * perUnit;
}

/** How often the dose is taken, and the text left once the frequency words are removed. */
interface Frequency {
  timesPerDay: number | null;
  daysPerWeek: number | null;
  everyOtherDay: boolean;
  weeklyAmount: boolean;
  daily: boolean;
  rest: string;
}

function readFrequency(text: string): Frequency {
  let rest = text;
  const take = (re: RegExp): RegExpMatchArray | null => {
    const m = rest.match(re);
    if (m) rest = `${rest.slice(0, m.index)} ${rest.slice((m.index ?? 0) + m[0].length)}`;
    return m;
  };
  const times = take(TIMES_PER_DAY);
  const days = take(DAYS_PER_WEEK);
  const everyOtherDay = take(EVERY_OTHER_DAY) !== null;
  const weeklyAmount = take(WEEKLY_AMOUNT) !== null;
  let daily = false;
  while (take(DAILY)) daily = true;
  rest = rest.replace(DURATION, " ");
  return {
    timesPerDay: times ? readCount(times[1] ?? times[2]) : null,
    daysPerWeek: days ? readCount(days[1]) : null,
    everyOtherDay,
    weeklyAmount,
    daily,
    rest,
  };
}

/** Grams taken each time, read from the text left once the frequency words are removed; null when no mass can be read. */
function gramsPerIntake(text: string): number | null {
