  let m = text.match(
    new RegExp(`(${COUNT})(?:\\s*${RANGE_SEPARATOR}\\s*${COUNT})?\\s*${SERVING}\\s*(?:(?:de|of)\\s+|[x*]\\s*)(${NUMBER})\\s*(${WORD})`),
