  // "2 x 5 g", "2x5g"
  m = text.match(new RegExp(`(${COUNT})\\s*[x*]\\s*(${NUMBER})\\s*(${WORD})`));
  if (m) {
    const each = grams(readNumber(m[2], unitOf(m[3])), unitOf(m[3]));
    if (each !== null) return readCount(m[1]) * each;
  }
