  m = text.match(new RegExp(`(${NUMBER})\\s*(${WORD})\\s*[x*]\\s*(${COUNT})`));
  if (m) {
    const each = grams(readNumber(m[1], unitOf(m[2])), unitOf(m[2]));
    if (each !== null) return each * readCount(m[3]);
  }
  // A range reads its lower end: "3 a 5 g", "entre 3 y 5 g", "3-5 g".
  m = text.match(new RegExp(`(${NUMBER})\\s*${RANGE_SEPARATOR}\\s*(${NUMBER})\\s*(${WORD})`));
  if (m) {
    const low = grams(readNumber(m[1], unitOf(m[3])), unitOf(m[3]));
    if (low !== null) return low;
  }
  // The first amount with a mass unit: "5 g", "1 cucharadita (5 g)".
  for (const amount of text.matchAll(new RegExp(`(${NUMBER})\\s*(${WORD})`, "g"))) {
    const g = grams(readNumber(amount[1], unitOf(amount[2])), unitOf(amount[2]));
    if (g !== null) return g;
  }
  // A number alone: grams below CREATINE_BARE_DOSE_MG_FROM, else milligrams.
  m = text.match(new RegExp(`^[\\s(),.;:-]*(${NUMBER})[\\s(),.;:]*$`));
  if (m) {
    const value = readNumber(m[1], null);
    return value >= CREATINE_BARE_DOSE_MG_FROM ? value / 1000 : value;
  }
  return null;
