 * ("1 cacito"), a dose per kilogram ("0,3 g/kg/día"), a slash between numbers
 * ("1/2 g"), or two ways of saying how often that disagree ("5 g al día, 3
 * días a la semana": every day, or three days a week?). The context form asks
 * for grams a day then (PatientContextGate). Zero when the dose is zero.
 */
export function readCreatineDose(dose: string | null | undefined): number | null {
  if (typeof dose !== "string") return null;
  const text = normalizeDose(dose);
  if (!text || PER_KG.test(text) || SLASH_BETWEEN_NUMBERS.test(text)) return null;
  const f = readFrequency(text);
  const weekly = [f.daysPerWeek !== null, f.everyOtherDay, f.weeklyAmount].filter(Boolean).length;
  if (weekly > 1 || (weekly === 1 && f.daily)) return null;
  if (f.timesPerDay !== null && !(f.timesPerDay > 0 && f.timesPerDay <= 10)) return null;
  if (f.daysPerWeek !== null && !(f.daysPerWeek > 0 && f.daysPerWeek <= 7)) return null;
