/**
 * What the real supabase-js returns to `.from("profiles").select("date_of_birth, sex").eq("id", u).single()`
 * (the read in recomputeLabFigures) when the request fails: a connection reset, a PostgREST 503, and a missing row.
 * No network: the client gets a fetch that never leaves the process.
 */
import { createClient } from "@supabase/supabase-js";

type Mode = "reset" | "503" | "no_row" | "ok";

function fetchFor(mode: Mode): typeof fetch {
  return (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(input);
    const headers = new Headers(init?.headers);
    if (mode === "reset") {
      const cause = Object.assign(new Error("read ECONNRESET"), { code: "ECONNRESET", name: "Error" });
      throw Object.assign(new TypeError("fetch failed"), { cause });
    }
    if (mode === "503") {
      return new Response(JSON.stringify({ code: "PGRST002", message: "Could not query the database for the schema cache. Retrying.", details: null, hint: null }), {
        status: 503,
        headers: { "content-type": "application/json" },
      });
    }
    const wantsObject = (headers.get("Accept") ?? "").includes("vnd.pgrst.object+json");
    if (mode === "no_row") {
      if (wantsObject) {
        return new Response(JSON.stringify({ code: "PGRST116", details: "The result contains 0 rows", hint: null, message: "Cannot coerce the result to a single JSON object" }), { status: 406, headers: { "content-type": "application/json" } });
      }
      return new Response("[]", { status: 200, headers: { "content-type": "application/json" } });
    }
    const row = { date_of_birth: "1979-06-02", sex: "male" };
    return new Response(JSON.stringify(wantsObject ? row : [row]), { status: 200, headers: { "content-type": "application/json", "x-url": url } });
  }) as typeof fetch;
}

async function main() {
  for (const mode of ["ok", "reset", "503", "no_row"] as Mode[]) {
    const client = createClient("http://supabase.invalid", "anon-key", {
      global: { fetch: fetchFor(mode) },
      auth: { persistSession: false, autoRefreshToken: false },
    });
    let outcome: unknown;
    try {
      const { data, error } = await client.from("profiles").select("date_of_birth, sex").eq("id", "u1").single();
      outcome = { threw: false, data, error: error ? { code: error.code, message: error.message } : null };
    } catch (e) {
      outcome = { threw: true, message: e instanceof Error ? e.message : String(e) };
    }
    let maybe: unknown;
    try {
      const { data, error } = await client.from("profiles").select("date_of_birth, sex").eq("id", "u1").maybeSingle();
      maybe = { threw: false, data, error: error ? { code: error.code, message: error.message } : null };
    } catch (e) {
      maybe = { threw: true, message: e instanceof Error ? e.message : String(e) };
    }
    console.log(JSON.stringify({ mode, single: outcome, maybeSingle: maybe }));
  }
}

main();
EOF
