import type { SupabaseClient } from "@supabase/supabase-js";

export type FakeCall = { table: string; ops: { op: string; args: unknown[] }[] };
export type FakeResponse = { data?: unknown; error?: unknown; count?: number | null };

const METHODS = ["insert", "select", "update", "upsert", "delete", "eq", "neq", "in", "is", "or", "not", "lt", "gt", "gte", "lte", "order", "limit", "range", "single", "maybeSingle"];

/** The keys a select returns, as PostgREST names them ("alias:col", "col::type", "embed!hint(...)"); null for "*". */
export function selectedKeys(select: string): string[] | null {
  const tokens: string[] = [];
  let depth = 0;
  let current = "";
  for (const ch of select) {
    if (ch === "(") depth++;
    if (ch === ")") depth--;
    if (ch === "," && depth === 0) {
      tokens.push(current.trim());
      current = "";
    } else current += ch;
  }
  tokens.push(current.trim());
  if (tokens.includes("*")) return null;
  return tokens.filter(Boolean).map((t) => (/^(\w+)\s*:(?!:)/.exec(t) ?? /^(\w+)/.exec(t))![1]);
}

function project(call: FakeCall, data: unknown): unknown {
  const select = call.ops.find((o) => o.op === "select")?.args[0];
  if (typeof select !== "string" || data == null || typeof data !== "object") return data;
  const keys = selectedKeys(select);
  if (!keys) return data;
  const pick = (row: unknown) =>
    row && typeof row === "object" ? Object.fromEntries(keys.filter((k) => k in row).map((k) => [k, (row as Record<string, unknown>)[k]])) : row;
  return Array.isArray(data) ? data.map(pick) : pick(data);
}

export function fakeSupabase(respond: (call: FakeCall) => FakeResponse) {
  const calls: FakeCall[] = [];
  const client = {
    from(table: string) {
      const call: FakeCall = { table, ops: [] };
      calls.push(call);
      const builder: Record<string, unknown> = {};
      for (const m of METHODS) {
        builder[m] = (...args: unknown[]) => {
          call.ops.push({ op: m, args });
          return builder;
        };
      }
      builder.then = (resolve: (v: unknown) => void, reject?: (e: unknown) => void) => {
        try {
          const r = respond(call);
          resolve({ data: null, error: null, count: null, ...r, ...("data" in r ? { data: project(call, r.data) } : {}) });
        } catch (e) {
          reject?.(e);
        }
      };
      return builder;
    },
  };
  return { client: client as unknown as SupabaseClient, calls };
}

/** "insert.select.single" — the builder chain of a recorded call. */
export const ops = (c: FakeCall): string => c.ops.map((o) => o.op).join(".");

/** The arguments of the first `op` in a recorded call, if any. */
export const argsOf = (c: FakeCall, op: string, matchFirstArg?: unknown): unknown[] | undefined =>
  c.ops.find((o) => o.op === op && (matchFirstArg === undefined || o.args[0] === matchFirstArg))?.args;
EOF
