  `(${COUNT})(?:\\s*${RANGE_SEPARATOR}\\s*${COUNT})?\\s*(?:de\\s+)?${SERVING}\\s*(?:(?:de|of)\\s+|[x*]\\s*|(?=\\d))(${NUMBER})\\s*(${WORD})`,
