/** A dose taken each time below this many grams is more likely a unit slip ("5 mg" for 5 g) than a dose: the form asks. */
const SMALLEST_CREATINE_INTAKE_G = 0.1;

/**
 * Grams of creatine per day in a free-text dose, as clients write it: "5 g",
 * "5 gramos al día", "5000 mg", "5" (grams below 100, else milligrams), "3 a
 * 5 g" (the lower end), "2 x 2,5 g", "2 cápsulas de 750 mg", "1 cacito (5 g)",
 * "2,5 g dos veces al día" (5), "5 g, 3 días a la semana" (5 × 3/7), "5 g en
 * días alternos" (2.5), "5 g cada 3 días" (5/3), "35 g a la semana" (5).
 *
 * Null when it cannot be read as a daily mass: no amount with a mass unit
 * ("1 cacito"), a dose per kilogram ("0,3 g/kg/día"), a slash between numbers
 * ("1/2 g"), two amounts that are not a range or a product ("1 g mañana y 1 g
 * noche", "20 g 5 días y luego 5 g"), two ways of saying how often that
 * disagree ("5 g al día, 3 días a la semana": every day, or three days a
 * week?), a schedule with no count ("5 g los lunes", "los días de entreno"), a
 * dose the client stopped ("ya no, antes 5 g"), or an intake under 0.1 g ("5
 * mg"). The context form asks for grams a day then, and shows what it read
 * otherwise (PatientContextGate). Zero when the dose is zero.
 */
export function readCreatineDose(dose: string | null | undefined): number | null {
  if (typeof dose !== "string") return null;
  const text = normalizeCreatineText(normalizeDose(dose));
  if (!text || PER_KG.test(text) || SLASH_BETWEEN_NUMBERS.test(text) || STOPPED.test(text)) return null;
  const f = readFrequency(text);
  const weekly = [f.daysPerWeek !== null, f.everyNDays !== null, f.weeklyAmount].filter(Boolean).length;
