  if (weekly === 0 && UNCOUNTED_SCHEDULE.test(f.rest)) return null;
  if (f.timesPerDay !== null && !(f.timesPerDay > 0 && f.timesPerDay <= 10)) return null;
  if (f.daysPerWeek !== null && !(f.daysPerWeek > 0 && f.daysPerWeek <= 7)) return null;
  if (f.everyNDays !== null && !(f.everyNDays >= 1 && f.everyNDays <= 7)) return null;
  const each = gramsPerIntake(f.rest);
  if (each === null || (each > 0 && each < SMALLEST_CREATINE_INTAKE_G)) return null;
  const perDay =
    (f.timesPerDay ?? 1) *
    (f.daysPerWeek !== null ? f.daysPerWeek / 7 : 1) *
    (f.everyNDays !== null ? 1 / f.everyNDays : 1) *
    (f.weeklyAmount ? 1 / 7 : 1);
  const g = each * perDay;
  return Number.isFinite(g) && g >= 0 ? g : null;
}

