type Row = Record<string, unknown>;

function matches(row: Row, c: FakeCall): boolean {
  for (const { op, args } of c.ops) {
    const [col, val] = args as [string, unknown];
    if (op === "eq" && row[col] !== val) return false;
    if (op === "neq" && row[col] === val) return false;
