  Object.entries({ ...BASE, creatinine: [0.9, 1.1, 1.6][i] }).map(([biomarker_key, value]) => ({ lab_result_id: l.id, biomarker_key, value })),
);

function db(fail: "window" | "latest" | null, labs = LABS) {
  let windowReads = 0;
