  const fake = fakeSupabase((c) => {
    if (c.table === "profiles" && ops(c).startsWith("select")) return { data: { sex: "male", date_of_birth: DOB } };
    if (c.table === "profiles" && ops(c).startsWith("update")) {
      cached.push(argsOf(c, "update")![0] as Record<string, unknown>);
      return { data: null };
