  ] as const;
const cronRequest = () =>
  new NextRequest("http://localhost/api/cron/auto-resolve-pending-context", { headers: { authorization: "Bearer s3cret" } });

describe("the client and the 72-hour cron never both resolve one lab", () => {
  beforeEach(() => {
    process.env.CRON_SECRET = "s3cret";
    vi.mocked(generateSummary).mockReset();
    vi.mocked(getCurrentVersion).mockReset();
    vi.mocked(sendEmail).mockClear();
    vi.spyOn(console, "error").mockImplementation(() => {});
    vi.spyOn(console, "log").mockImplementation(() => {});
  });
  afterEach(() => vi.restoreAllMocks());

  it("a cron run that fails before its claim leaves the client's claim alone: one AI run, one email", async () => {
    const db = database();
    const firstAi = deferred<void>();
    vi.mocked(generateSummary).mockImplementationOnce(() => firstAi.promise).mockImplementation(async () => undefined);
    const versionRead = deferred<{ id: string }>();
    vi.mocked(getCurrentVersion).mockImplementation(() => versionRead.promise as never);

    // The cron lists the lab while it is pending; the client then claims it and waits on its AI step.
    const cronRun = cron(cronRequest());
    await vi.waitFor(() => expect(getCurrentVersion).toHaveBeenCalled());
    const first = confirm(...confirmRequest());
    await vi.waitFor(() => expect(generateSummary).toHaveBeenCalledTimes(1));
    // The cron's read fails before its own claim: its reset must not release the client's lab.
    versionRead.reject(new Error("Failed to load patient context: connection reset"));
    const cronBody = await (await cronRun).json();
    expect(cronBody.results).toEqual([expect.objectContaining({ id: LAB, ok: false })]);
    expect(db.lab.status).toBe("processing");
    expect((await confirm(...confirmRequest())).status).toBe(409);

    firstAi.resolve();
    expect((await first).status).toBe(200);
    expect(db.lab).toMatchObject({ status: "ready", patient_context_version_id: V2 });
    expect(generateSummary).toHaveBeenCalledTimes(1);
    expect(sendEmail).toHaveBeenCalledTimes(1);
    expect(db.history).toEqual(["client: processing", "client: ready"]);
  });

  it("a cron run that fails after its own claim puts the lab back to pending_context", async () => {
    const db = database({ noValues: true });
    vi.mocked(getCurrentVersion).mockResolvedValue({ id: "v-latest" } as never);
    const cronBody = await (await cron(cronRequest())).json();
