    const state = rules.reasons.some((r) => r.code === "pregnancy" || r.code === "lactation");
    return {
      ...identity,
      ...noResult,
      ...(state ? { hba1c_source: null, hba1c_excluded_reason: null } : hba1c),
      reason: rules.reasons[0].code,
      reasons: rules.reasons,
      ...gating,
      bounded_markers: state ? [] : a.boundedMarkers,
      ...laboratory,
      ...creatine,
    };
  }

  const outcome = computeBiologicalAgeV3(a.inputs, a.sex, a.age);
  if (outcome.ba === null) {
    const ageUnknown = outcome.reason === "age_outside_validated_range" && !Number.isFinite(a.age);
    const implausible =
      outcome.reason === "missing_markers" && outcome.markers.some((k) => a.implausibleMarkers.includes(k));
    const reason: BioAgeV3Reason = ageUnknown ? "age_unknown" : implausible ? "implausible_value" : outcome.reason;
    return {
      ...identity,
      ...noResult,
      ...hba1c,
      reason,
      reasons: [moduleReason(reason, outcome.markers)],
      ...gating,
      bounded_markers: a.boundedMarkers,
      ...laboratory,
      ...creatine,
    };
  }
  return {
    ...identity,
    tier: outcome.tier,
    ba: outcome.ba,
    interval_low: outcome.interval[0],
    interval_high: outcome.interval[1],
    markers_used: outcome.markersUsed,
    clamps_applied: outcome.clampsApplied,
    crp_capped: outcome.crpCapped,
    provisional: outcome.crpCapped || rules.provisional,
    ...hba1c,
    reason: null,
    reasons: [],
    ...gating,
    bounded_markers: a.boundedMarkers,
    ...laboratory,
    ...creatine,
  };
}

/** A module refusal as a `reasons` entry. */
function moduleReason(code: BioAgeV3Reason, markers: readonly string[]): BioAgeV3ReasonEntry {
  const keys = [...new Set(markers)];
  const detail = `version 3 module: ${code}${keys.length > 0 ? ` (${keys.join(", ")})` : ""}`;
  return keys.length === 1 ? { code, marker: keys[0], detail } : { code, detail };
}

