def ckd(cr, age, sex):
    k = 0.7 if sex == 'female' else 0.9
    a = -0.241 if sex == 'female' else -0.302
    r = cr / k
    return 142 * min(r, 1) ** a * max(r, 1) ** -1.2 * 0.9938 ** age * (1.012 if sex == 'female' else 1)

def quantiles(pct):
    pts = []
    for kk, v in pct.items():
        p = float(kk.replace('p', '').replace('_', '.'))
        pts.append((p / 100, v))
    return sorted(pts)

def cdf(q, x):
    if x < q[0][1]:
        return 0.0
    if x == q[0][1]:
        return q[0][0]
    for i in range(1, len(q)):
        p0, v0 = q[i - 1]
        p1, v1 = q[i]
        if x <= v1:
            return p1 if v1 == v0 else p0 + (p1 - p0) * (x - v0) / (v1 - v0)
    return 1.0

def cr_for_egfr(target, age, sex):
    lo, hi = 0.05, 10.0
    for _ in range(200):
        mid = (lo + hi) / 2
        if ckd(mid, age, sex) > target:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2

