// Edit columns of one upsert row of migration.sql (the compile's format: one row per line inside VALUES).
// setCols: { column: "raw SQL literal" }. Returns the new migration text.
function editMigRow(mig, key, sex, age, setCols) {
  const lines = mig.split("\n");
  const head = lines.find((l) => l.startsWith("insert into public.biomarker_references ("));
  const cols = head.slice(head.indexOf("(") + 1, head.indexOf(")")).split(",").map((c) => c.trim());
  const split = (body) => {
    const out = []; let cur = ""; let q = false; let depth = 0;
    for (let i = 0; i < body.length; i++) {
      const ch = body[i];
      if (q) { cur += ch; if (ch === "'") { if (body[i + 1] === "'") { cur += "'"; i++; } else q = false; } continue; }
      if (ch === "'") q = true; else if (ch === "[" || ch === "(") depth++; else if (ch === "]" || ch === ")") depth--;
      if (ch === "," && depth === 0) { out.push(cur.trim()); cur = ""; continue; }
      cur += ch;
    }
    out.push(cur.trim());
    return out;
  };
  let hits = 0;
  const outLines = lines.map((l) => {
    const m = l.match(/^  \((.*)\)(,?)$/);
    if (!m) return l;
    const vals = split(m[1]);
    if (vals.length !== cols.length) return l;
    const v = (c) => vals[cols.indexOf(c)];
    if (v("biomarker_key") !== `'${key}'` || v("sex") !== `'${sex}'` || v("age_group_en") !== `'${age}'`) return l;
    hits++;
    for (const [c, raw] of Object.entries(setCols)) { if (!cols.includes(c)) throw new Error(`no column ${c}`); vals[cols.indexOf(c)] = raw; }
    return `  (${vals.join(", ")})${m[2]}`;
  });
  if (hits !== 1) throw new Error(`expected one upsert row ${key}|${sex}|${age}, found ${hits}`);
  return outLines.join("\n");
}
module.exports.editMigRow = editMigRow;
EOF
