  for (const m of text.matchAll(re)) { const raw = m[1]; if (/^(19|20)\d\d$/.test(raw)) continue; const n = Number(lang === "es" ? raw.replace(/\./g, "").replace(",", ".") : raw.replace(/,/g, "")); if (Number.isFinite(n)) out.push(n); }
  return out;
}
const CLOSER = { en: lex.en.required.out_of_range_closer, es: lex.es.required.out_of_range_closer };
const CRIT = { en: lex.en.required.critical_closer, es: lex.es.required.critical_closer };
const URG = { en: ["Book an appointment with your doctor in the next few weeks", "Discuss it with your doctor at your next check-up"], es: ["Pide cita con tu médico en las próximas semanas", "Coméntalo con tu médico en tu próxima revisión"] };
