const ch = JSON.parse(fs.readFileSync(dir + "/changes.json", "utf8")).changes;
const readIf = (p) => (fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, "utf8")) : null);
const canon = (v) => v === undefined || v === null ? "null" : typeof v !== "object" ? JSON.stringify(v) : Array.isArray(v) ? `[${v.map(canon).join(",")}]` : `{${Object.keys(v).sort().map((k) => JSON.stringify(k) + ":" + canon(v[k])).join(",")}}`;
const eq = (a, b) => canon(a) === canon(b);
