const CORE = ["reference_low", "reference_high", "optimal_low", "optimal_high", "critical_low", "critical_high", "unit", "grade"];
const stats = { verdict: 0, verdict_neutral: 0, verdict_note: 0, corr: 0, problems: [] };
const perRowVerdicts = {};
for (const c of ch) {
  if (c.reason_from !== "verify.row_verdicts" && c.reason_from !== "verify.corrections") continue;
  const d = fam(c.family);
  const compiledRows = c.source === "decisions" ? d.decision.final_rows : c.source === "verify" ? d.verify.final_rows : d.research.rows;
  const row = compiledRows.filter((r) => lkOf(r) === c.loop_row_key).pop();
  const ver = (d.verify?.final_rows || []).filter((r) => lkOf(r) === c.loop_row_key).pop();
  const verdicts = (d.verify?.row_verdicts || []).filter((v) => v.row_key === c.loop_row_key);
  const coreDiff = CORE.filter((k) => !eq(row?.[k], ver?.[k]));
  const otherDiff = [...new Set([...Object.keys(row || {}), ...Object.keys(ver || {})])].filter((k) => !CORE.includes(k) && !eq(row?.[k], ver?.[k]));
  if (c.reason_from === "verify.row_verdicts") {
    stats.verdict++;
    perRowVerdicts[c.loop_row_key] = verdicts.length;
    const neutral = /is not repeated here\.$/.test(c.reason);
    if (neutral) stats.verdict_neutral++; else stats.verdict_note++;
    if (!row || !ver) stats.problems.push(["no row/verified", c.row_key, c.field]);
    if (!verdicts.length) stats.problems.push(["no verdicts", c.row_key, c.field]);
    if (verdicts.some((v) => !["confirmed", "corrected"].includes(v.verdict))) stats.problems.push(["bad verdict", c.row_key, c.field]);
    if (coreDiff.length) stats.problems.push(["core differs", c.row_key, c.field, coreDiff]);
