import json, os, collections
S='$S/briefs'; W='docs/signoff/work/briefs'
diffs=collections.Counter()
def walk(a,b,p,out):
    if type(a)!=type(b): out.append((p,a,b)); return
    if isinstance(a,dict):
        for k in set(a)|set(b):
            if k not in a or k not in b: out.append((p+'/'+k, a.get(k,'<absent>'), b.get(k,'<absent>')))
            else: walk(a[k],b[k],p+'/'+k,out)
    elif isinstance(a,list):
        if len(a)!=len(b): out.append((p,'len %d'%len(a),'len %d'%len(b))); return
        for i,(x,y) in enumerate(zip(a,b)): walk(x,y,p+'/%d'%i,out)
    elif a!=b: out.append((p,a,b))
ex=None
for f in sorted(os.listdir(S)):
    a=json.load(open(os.path.join(W,f))); b=json.load(open(os.path.join(S,f)))
    out=[]; walk(a,b,'',out)
    for p,x,y in out:
        diffs[p]+=1
        if ex is None: ex=(f,out)
print(dict(diffs))
f,out=ex
for p,x,y in out:
    print(f,p); print('   worktree brief:', str(x)[:400]); print('   rebuilt       :', str(y)[:400])
