// Mutation harness: for each mutant, copy the isolated tools tree, apply one textual edit, run the tests, report.
const fs = require("fs"), path = require("path"), { spawnSync } = require("child_process");
const S = __dirname, BASE = path.join(S, "mut-base");
const mutants = require(path.resolve(process.argv[2]));
const only = process.argv[3] ? new Set(process.argv[3].split(",")) : null;
const TESTS = (process.env.MUT_TESTS || "docs/signoff/tools/test/compile.test.js docs/signoff/tools/test/compile-diff.test.js").split(" ");
function copyDir(a, b) { fs.mkdirSync(b, { recursive: true }); for (const e of fs.readdirSync(a, { withFileTypes: true })) { const x = path.join(a, e.name), y = path.join(b, e.name); if (e.isDirectory()) copyDir(x, y); else fs.copyFileSync(x, y); } }
const results = [];
for (const m of mutants) {
  if (only && !only.has(m.id)) continue;
  const dir = path.join(S, "mut-run", m.id);
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(path.join(dir, "docs/signoff"), { recursive: true });
  copyDir(path.join(BASE, "docs/signoff/tools"), path.join(dir, "docs/signoff/tools"));
  // data: links inside the scratch area only (mut-base holds real copies, not the checkouts)
  fs.symlinkSync(path.join(BASE, "supabase"), path.join(dir, "supabase"));
  fs.symlinkSync(path.join(BASE, "docs/biomarker-evidence"), path.join(dir, "docs/biomarker-evidence"));
  fs.symlinkSync(path.join(BASE, "docs/signoff/work"), path.join(dir, "docs/signoff/work"));
  const file = path.join(dir, m.file);
  let src = fs.readFileSync(file, "utf8");
  const n = src.split(m.find).length - 1;
  if (n !== 1) { results.push({ id: m.id, error: `find text occurs ${n} times` }); console.log(m.id, "ERROR find occurs", n); continue; }
  src = src.replace(m.find, () => m.replace);
  fs.writeFileSync(file, src);
  const p = spawnSync(process.execPath, ["--test", ...TESTS], { cwd: dir, encoding: "utf8", env: { ...process.env, TMPDIR: path.join(S, "tmp") }, maxBuffer: 64 * 1024 * 1024 });
  const out = p.stdout + p.stderr;
  const failed = [...out.matchAll(/^not ok \d+ - (.*)$/gm)].map((x) => x[1]);
  const pass = (out.match(/^# pass (\d+)/m) || [])[1], fail = (out.match(/^# fail (\d+)/m) || [])[1];
  results.push({ id: m.id, what: m.what, killed: failed.length > 0, pass, fail, failed });
  console.log(`${failed.length ? "KILLED  " : "SURVIVED"} ${m.id}: ${m.what} [pass ${pass}, fail ${fail}]${failed.length ? "\n      by: " + failed.map((f) => f.slice(0, 110)).join("\n          ") : ""}`);
  fs.rmSync(dir, { recursive: true, force: true });
}
fs.writeFileSync(path.join(S, `mut-results-${path.basename(process.argv[2], ".js")}.json`), JSON.stringify(results, null, 2));
EOF
