import { POST as webhook } from "@/app/api/lab-results/webhook/route";

const LAB = "11111111-1111-4111-8111-111111111111";
const REFS = [
  { biomarker_key: "hs_crp", sex: "both", age_group_en: "All Adults", optimal_low: null, optimal_high: 0.5, normal_low: 0, normal_high: 3, panel_category: "heart" },
  { biomarker_key: "glucose_fasting", sex: "both", age_group_en: "All Adults", optimal_low: 70, optimal_high: 90, normal_low: 65, normal_high: 99, panel_category: "metabolic" },
