];

type Row = Record<string, unknown>;

function editDb(row: Row) {
  const updates: Row[] = [];
  const respond = (c: FakeCall): FakeResponse => {
    const op = ops(c);
    if (c.table === "biomarker_values" && op.startsWith("select")) return { data: row };
    if (c.table === "biomarker_values" && op.startsWith("update")) {
      const u = argsOf(c, "update")?.[0] as Row;
      updates.push(u);
      return { data: { ...row, ...u } };
    }
    if (c.table === "profiles") return { data: { date_of_birth: "1981-03-15", sex: "male" } };
    if (c.table === "biomarker_references") {
      const key = argsOf(c, "eq")?.[1];
      return { data: REFS.filter((r) => r.biomarker_key === key) };
    }
    return { data: null };
  };
  const { client, calls } = fakeSupabase(respond);
  state.client = Object.assign(client, { auth: { getUser: async () => ({ data: { user: { id: "u1" } } }) } });
  return { updates, calls };
}

const stored = (over: Row = {}): Row => ({
  id: "bv-1", lab_result_id: LAB, biomarker_key: "hs_crp", biomarker_name: "PCR ultrasensible", value: 1.75, unit: "mg/L", comparator: "<", zone: "unclassified",
  lab_results: { user_id: "u1", collection_date: "2026-10-01" }, ...over,
});

async function patch(body: unknown) {
  const res = await edit(new NextRequest("http://localhost/api/biomarker-values/bv-1", { method: "PATCH", body: JSON.stringify(body) }), { params: Promise.resolve({ id: "bv-1" }) });
  return { status: res.status, json: (await res.json()) as Row };
}

