  afterAll(() => vi.restoreAllMocks());

  it("Edit and Save on a stored '<1.75' keeps the comparator and never classifies above optimal", async () => {
    const db = editDb(stored());
    const r = await patch({ value: 1.75 });
    expect(r.status).toBe(200);
    expect(db.updates).toHaveLength(1);
    expect(db.updates[0]).toMatchObject({ value: 1.75, unit: "mg/L", comparator: "<", zone: "unclassified" });
  });
  it("'<0.2' is optimal, '<5' (the specification's example) is unclassified, with a unit-only edit too", async () => {
    let db = editDb(stored());
    await patch({ value: 0.2 });
    expect(db.updates[0]).toMatchObject({ value: 0.2, comparator: "<", zone: "optimal" });
    db = editDb(stored());
    await patch({ value: 5 });
    expect(db.updates[0]).toMatchObject({ value: 5, comparator: "<", zone: "unclassified" });
    db = editDb(stored());
    await patch({ value: 1.75, unit: "mg/L" });
    expect(db.updates[0]).toMatchObject({ comparator: "<", zone: "unclassified" });
  });
  it("comparator null in the body clears it: the value is then a measured one", async () => {
    const db = editDb(stored());
    const r = await patch({ value: 1.75, comparator: null });
    expect(r.status).toBe(200);
    expect(db.updates[0]).toMatchObject({ value: 1.75, comparator: null, zone: "above_optimal" });
  });
  it("a measured row stays measured, and the body can set a comparator", async () => {
    let db = editDb(stored({ comparator: null, zone: "above_optimal" }));
    await patch({ value: 1.75 });
    expect(db.updates[0]).toMatchObject({ value: 1.75, comparator: null, zone: "above_optimal" });
    db = editDb(stored({ comparator: null, zone: "above_optimal" }));
    await patch({ value: 5 });
    expect(db.updates[0]).toMatchObject({ value: 5, comparator: null, zone: "critical_high" });
    db = editDb(stored({ comparator: null, zone: "above_optimal" }));
    await patch({ value: 5, comparator: "<" });
    expect(db.updates[0]).toMatchObject({ value: 5, comparator: "<", zone: "unclassified" });
    db = editDb(stored({ comparator: undefined }));
    await patch({ value: 5 });
    expect(db.updates[0]).toMatchObject({ value: 5, comparator: null, zone: "critical_high" });
  });
  it("'>' results: '>12' is out of range, '>2' cannot be placed, a low marker '<150' under its floor is out of range", async () => {
    let db = editDb(stored({ comparator: ">", value: 12 }));
    await patch({ value: 12 });
    expect(db.updates[0]).toMatchObject({ value: 12, comparator: ">", zone: "critical_high" });
    db = editDb(stored({ comparator: ">", value: 12 }));
    await patch({ value: 2 });
    expect(db.updates[0]).toMatchObject({ value: 2, comparator: ">", zone: "unclassified" });
    db = editDb(stored({ biomarker_key: "vitamin_b12", unit: "pg/mL", comparator: "<", value: 150 }));
    await patch({ value: 150 });
    expect(db.updates[0]).toMatchObject({ value: 150, comparator: "<", zone: "critical_low" });
  });
  it("a kept '<' on a value retyped far higher: unclassified, where the measured number would be out of range", async () => {
    const db = editDb(stored());
    await patch({ value: 50 });
    expect(db.updates[0]).toMatchObject({ value: 50, comparator: "<", zone: "unclassified" });
  });
  it("a converted bound keeps its comparator (glucose '<2.0 mmol/L' is below the range)", async () => {
    const db = editDb(stored({ biomarker_key: "glucose_fasting", unit: "mg/dL", value: 36, comparator: "<" }));
    const r = await patch({ value: 2.0, unit: "mmol/L" });
    expect(r.status).toBe(200);
    expect(db.updates[0]).toMatchObject({ unit: "mg/dL", comparator: "<", zone: "critical_low" });
    expect(db.updates[0].value as number).toBeCloseTo(36.0364, 3);
  });
  it("a comparator other than '<', '>' or null is refused and nothing is written", async () => {
    for (const bad of ["<=", ">=", "", "=", 5, "≤", "lt"]) {
      const db = editDb(stored());
