      expect(r.status, String(bad)).toBe(400);
      expect(db.updates).toHaveLength(0);
    }
  });
  it("no reference row: unclassified, comparator still written as kept", async () => {
    const db = editDb(stored({ biomarker_key: "no_such_marker", unit: "x" }));
    await patch({ value: 1 });
    expect(db.updates[0]).toMatchObject({ comparator: "<", zone: "unclassified" });
  });
});

function pipelineDb(storedRows: Row[]) {
  const inserted: Row[] = [];
  const respond = (c: FakeCall): FakeResponse => {
    const op = ops(c);
    if (c.table === "lab_results" && op.startsWith("insert")) return { data: { id: LAB } };
    if (c.table === "lab_results" && op.startsWith("select")) return { data: { id: LAB, user_id: "u1", collection_date: null, patient_context_version_id: null, created_at: "2026-10-01" } };
    if (c.table === "profiles") return { data: { date_of_birth: "1981-03-15", sex: "male" } };
    if (c.table === "biomarker_references") return { data: REFS };
    if (c.table === "biomarker_values" && op.startsWith("select")) {
      const sel = argsOf(c, "select") as [string, { head?: boolean }?];
      if (sel?.[1]?.head) return { data: null, count: 0 };
      return { data: storedRows };
    }
    if (c.table === "biomarker_values" && op.startsWith("insert")) {
      inserted.push(...(argsOf(c, "insert")?.[0] as Row[]));
      return { data: null };
    }
    return { data: null };
  };
  // project: a row holds only the columns its select named, as PostgREST returns it
  const { client, calls } = fakeSupabase(respond, { project: true });
  const c = Object.assign(client, { auth: { getUser: async () => ({ data: { user: { id: "u1" } } }) } });
  state.client = c;
  state.admin = c;
  return { inserted, calls };
}

