/**
 * The sentences the app shows for a result it does not use (decisions D-24 and D-37), generated from the tables of
 * `set_aside` codes in docs/signoff/work/governance/wording-rules.md, section 7: the Spanish of Part I (the signed
 * version) and the English of Part II. The module it writes, src/lib/lab-results/set-aside-copy.generated.ts, is
 * never edited by hand (decision D-36).
 *
 *   npx tsx scripts/wording/set-aside-copy.ts            writes the module
 *   npx tsx scripts/wording/set-aside-copy.ts --check    exits 1 when the module differs from the tables
 *
 * The test suite runs the same comparison (src/lib/lab-results/set-aside.test.ts), so a sentence changed in one
 * place only fails the build.
 */
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";

export const RULES_FILE = "docs/signoff/work/governance/wording-rules.md";
export const MODULE_FILE = "src/lib/lab-results/set-aside-copy.generated.ts";

/** Every code a table must carry, in the order the module lists them. */
export const SET_ASIDE_CODES = [
  "heading",
  "tag",
  "intro_some",
  "intro_all",
  "reason.sign_not_storable",
  "reason.unit_not_convertible",
  "reason.value_unreadable",
  "reason.marker_not_recognised",
] as const;

/** The placeholders each sentence must use, no more and no fewer. */
const PLACEHOLDERS: Partial<Record<(typeof SET_ASIDE_CODES)[number], string[]>> = {
  "reason.sign_not_storable": ["sign"],
  "reason.unit_not_convertible": ["expected_unit", "unit"],
};

type Lang = "es" | "en";

/** The `set_aside` rows of one part of the document: code → sentence. */
function tableOf(part: string, lang: Lang): Record<string, string> {
  const rows: Record<string, string> = {};
  for (const line of part.split("\n")) {
    const m = /^\| `set_aside\.([a-z_.]+)` \| (.+) \|$/.exec(line.trim());
    if (!m) continue;
    if (m[1] in rows) throw new Error(`${RULES_FILE}: set_aside.${m[1]} appears twice in the ${lang} table`);
    rows[m[1]] = m[2].trim();
  }
  const missing = SET_ASIDE_CODES.filter((c) => !rows[c]);
  const extra = Object.keys(rows).filter((c) => !(SET_ASIDE_CODES as readonly string[]).includes(c));
  if (missing.length) throw new Error(`${RULES_FILE}: the ${lang} table lacks set_aside.${missing.join(", set_aside.")}`);
  if (extra.length) throw new Error(`${RULES_FILE}: the ${lang} table has unknown codes set_aside.${extra.join(", set_aside.")}`);
  for (const code of SET_ASIDE_CODES) {
    const used = [...rows[code].matchAll(/\{([a-z_]+)\}/g)].map((x) => x[1]).sort();
    const wanted = PLACEHOLDERS[code] ?? [];
    if (used.join(",") !== wanted.join(",")) {
      throw new Error(`${RULES_FILE}: set_aside.${code} (${lang}) must use the placeholders {${wanted.join("}, {")}} and has {${used.join("}, {")}}`);
    }
  }
  return rows;
}

/** The copy of both languages, read from the document's text. */
export function readSetAsideCopy(rules: string): Record<Lang, Record<string, string>> {
  const partTwo = rules.indexOf("\n## Part II.");
  const partThree = rules.indexOf("\n## Part III.");
  if (partTwo < 0 || partThree < partTwo) throw new Error(`${RULES_FILE}: Part II or Part III not found`);
  return { es: tableOf(rules.slice(0, partTwo), "es"), en: tableOf(rules.slice(partTwo, partThree), "en") };
}

function block(rows: Record<string, string>): string {
  const line = (key: string, code: string, indent: string) => `${indent}${key}: ${JSON.stringify(rows[code])},`;
  return [
    "{",
    line("heading", "heading", "    "),
    line("tag", "tag", "    "),
    line("intro_some", "intro_some", "    "),
    line("intro_all", "intro_all", "    "),
    "    reasons: {",
    ...SET_ASIDE_CODES.filter((c) => c.startsWith("reason.")).map((c) => line(c.slice("reason.".length), c, "      ")),
    "    },",
    "  }",
  ].join("\n");
}

/** The generated module's text for the given document text. */
export function buildSetAsideCopyModule(rules: string): string {
  const copy = readSetAsideCopy(rules);
  const version = /^Versión: `([^`]+)`/m.exec(rules)?.[1] ?? "unknown";
  // The hash covers the sentences only, so an edit elsewhere in the document does not change the module.
  const hash = createHash("sha256").update(JSON.stringify(copy)).digest("hex").slice(0, 16);
