    `// ${RULES_FILE}, section 7 (Part I, Spanish; Part II, English). Do not edit:`,
    "// change the sentence in that document and run `npx tsx scripts/wording/set-aside-copy.ts`.",
    "",
    "export const SET_ASIDE_COPY = {",
    `  rulesVersion: ${JSON.stringify(version)},`,
    `  sentencesHash: ${JSON.stringify(hash)},`,
    `  es: ${block(copy.es)},`,
    `  en: ${block(copy.en)},`,
    "} as const;",
    "",
  ].join("\n");
}

function main() {
  const root = path.resolve(__dirname, "../..");
  const wanted = buildSetAsideCopyModule(fs.readFileSync(path.join(root, RULES_FILE), "utf8"));
  const target = path.join(root, MODULE_FILE);
  if (process.argv.includes("--check")) {
    const have = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : "";
