describe("Out-of-range cap: a scored marker outside its reference interval rules out the top grade", () => {
  // 1% past a reference limit: the smallest out-of-range result. Null when the row has no usable limit on a side.
  function onePercentPast(row: ReviewedRange, side: "low" | "high"): number | null {
    const limit = side === "low" ? row.normal_low : row.normal_high;
    if (limit == null || limit <= 0) return null;
    const v = side === "low" ? limit * 0.99 : limit * 1.01;
    const zone = classifyZone(v, row.optimal_low, row.optimal_high, row.normal_low, row.normal_high);
    return zone === "critical_low" || zone === "critical_high" ? v : null;
  }

  it("the cap is the top of the grade below the top grade, as the engine grades scores", () => {
    // The level is graded as the cap's grade, and one point more is the top grade: read off two scored panels.
