      if (code === "EGFR" || !Number.isFinite(lo) || !Number.isFinite(hi)) return optimalBand(row).find(Number.isFinite) ?? 1;
      return ["APOB", "HOMA_IR", "HSCRP", "INSULIN", "TG", "LPA"].includes(code) ? lo : (lo + hi) / 2;
    });
    const row = pickReferenceRows(SEED, "male", 45).picked.get("magnesium_serum")!;
    const capped = calculateLongevityScoreV2(withValue(man, "MAGNESIUM", onePercentPast(row, "high")!), "male", 45, SEED);
