    expect(capped.cap!.uncappedScore).toBeGreaterThan(OUT_OF_RANGE_CAP.level); // the cap lowered it
    expect(capped).toMatchObject({ longevityScore: OUT_OF_RANGE_CAP.level, lsGrade: OUT_OF_RANGE_CAP.grade });
    expect(capped.lsGrade).not.toBe("Elite");
    // Without the marker the panel scores 100: its impact is the whole difference, cap included.
    expect(capped.markerScores.find((m) => m.code === "MAGNESIUM")?.lsPointsImpact).toBe(100 - OUT_OF_RANGE_CAP.level);
    // One point above the level is the top grade: an in-range panel that nets that score.
    const tops = new Map<number, string>();
    const rnd = random(5);
    for (let i = 0; i < 400 && !tops.has(OUT_OF_RANGE_CAP.level + 1); i++) {
      const inputs = panel("male", 45, (r) => {
        const [lo, hi] = optimalBand(r);
        if (rnd() < 0.85 || r.normal_high == null || !Number.isFinite(hi)) return optimalBand(r).find(Number.isFinite) ?? 1;
        return hi + rnd() * (r.normal_high - hi) * 0.999 + (lo - lo);
      });
      const r = calculateLongevityScoreV2(inputs, "male", 45, SEED);
