      const picked = pickReferenceRows(SEED, sex, age).picked;
      for (const code of scoredCodes) {
        for (const side of ["low", "high"] as const) {
          const value = onePercentPast(picked.get(REVIEWED_ROW_KEY[code])!, side);
          if (value == null) continue;
          tested++;
          const r = calculateLongevityScoreV2(withValue(base, code, value), sex, age, SEED);
          expect(r.longevityScore, `${sex} ${age} ${code} ${side}`).toBeLessThanOrEqual(OUT_OF_RANGE_CAP.level);
          expect(r.lsGrade, `${sex} ${age} ${code} ${side}`).not.toBe("Elite");
          // The cap is recorded exactly when it lowered the score, with the marker that holds it.
          if (r.cap) expect(r.cap).toMatchObject({ level: OUT_OF_RANGE_CAP.level, markers: [code] });
          expect(r.cap !== null, `${sex} ${age} ${code} ${side}`).toBe(r.cap !== null && r.cap.uncappedScore > r.longevityScore);
        }
