// Challenger's harness: runs the real ws1-batch.js body with scripted agents under the Workflow tool's documented rules.
import fs from 'node:fs'

export function loadScript(file) {
  let src = fs.readFileSync(file, 'utf8')
  // strip "export const meta = {...}" (a pure literal that ends at the first line that is exactly "}")
  const start = src.indexOf('export const meta')
  if (start !== 0) throw new Error('meta not first')
  const end = src.indexOf('\n}\n', start)
  src = src.slice(end + 3)
  const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
  return new AsyncFunction('args', 'agent', 'pipeline', 'parallel', 'log', 'phase', 'budget', 'workflow', src)
}

export async function pipeline(items, ...stages) {
  return Promise.all(items.map(async (item, index) => {
    let prev = item
    try {
      for (let i = 0; i < stages.length; i++) prev = await stages[i](prev, item, index)
      return prev
    } catch (e) {
      return null
    }
  }))
}
export async function parallel(thunks) {
  return Promise.all(thunks.map(async (t) => { try { return await t() } catch (e) { return null } }))
}

/**
 * run(file, args, world): world.agent(label, prompt, opts) returns the scripted result (or null, or throws).
 * Returns {result, logs, calls, error}.
 */
export async function run(file, args, world) {
  const fn = loadScript(file)
  const logs = []
  const calls = []
  const agent = async (prompt, opts) => {
    calls.push({ label: opts.label, phase: opts.phase, model: opts.model, effort: opts.effort, prompt })
    const r = await world.agent(opts.label, prompt, opts)
    return r
  }
  let result, error = null
  try {
    result = await fn(args, agent, pipeline, parallel, (m) => logs.push(m), () => {}, { total: null, spent: () => 0, remaining: () => Infinity }, async () => { throw new Error('no nested workflow') })
  } catch (e) { error = e }
  return { result, logs, calls, error }
}

// ─── a default scripted world ───
export function makeWorld(over = {}) {
  const fams = over.families || ['f03_kidney']
  const batch = over.batch || 'BXX'
  const state = { ledgerPayloads: [], runSummaries: [], prompts: {} }
  const famDef = (f) => ({ family: f, title: f, keys: [f.replace(/^f\d+_/, '') + '_k'], v3_keys: [], base_panel_keys: [], research_valid: !!(over.research_valid ?? false), verify_valid: !!(over.verify_valid ?? false) })
  const world = {
    state,
    async agent(label, prompt, opts) {
      state.prompts[label] = prompt
      if (over.hook) { const h = await over.hook(label, prompt, opts, state); if (h !== undefined) return h }
      let m
      if (label.startsWith('setup ')) return { batch, families: fams.map(famDef), existing_issues: over.existing_issues || [], inputs_missing: [], model: 'm' }
      if ((m = label.match(/^(author|verifier|fixer|author-repair|verifier-repair|fixer-repair|evidence-repair) (\S+) r(\d+)/))) return { file: 'x', valid: true, errors: [], searches_used: 0, files_written: [], model: 'm' }
      if ((m = label.match(/^check (\S+) r(\d+)/))) {
        const f = m[1], n = Number(m[2])
        const base = { family: f, round: n, valid: { research: true, verify: true, decision: null }, validation_errors: [], ownership_ok: true, outside_paths: [], compile_exit: 0, compile_ok: true, notes_not_reviewed: [], checks_file: `docs/signoff/work/checks/${f}-r${n}.json`, failing_count: 0, failing: [], blocked_checks: [], family_keyed: [], errors: [], model: 'm' }
        const o = over.check ? over.check(f, n, base) : undefined
        return o === undefined ? base : o
      }
      if ((m = label.match(/^judge-prep (\S+) r(\d+)/))) {
        const n = Number(m[2])
        const base = { round: n, compile_exit: 0, compile_ok: true, notes_lines: 0, checks_file: 'c', samples: [], errors: [], model: 'm' }
        const o = over.prep ? over.prep(n, base) : undefined
        return o === undefined ? base : o
      }
      if ((m = label.match(/^judge (J\d) (\S+) r(\d+)/))) {
        const lens = m[1], shard = m[2], n = Number(m[3])
        const families = shard.split('.').slice(1)
        const base = { file: `docs/signoff/work/judges/round-${n}/${lens}-${shard}.json`, valid: true, errors: [], lens, families_reviewed: families, blocking: [], minor: [], searches_used: 0, model: 'm' }
        const o = over.judge ? over.judge(lens, families, n, base) : undefined
