      }
      if ((m = label.match(/^ledger (\S+) (?:r(\d+)|final)/))) {
        const pm = prompt.match(/Payload:\n```json\n(.*)\n```/)
        const payload = JSON.parse(pm[1])
        const rm = prompt.match(/Run summary:\n```json\n(.*)\n```/)
        state.ledgerPayloads.push(payload)
        state.runSummaries.push(JSON.parse(rm[1]))
        const counts = over.counts ? over.counts(payload, state) : fams.map((f) => ({ family: f, blocking_open: 0, confirmed: 0, disputed: 0, unreviewed: 0, script_open: 0 }))
        if (counts === null) return null
        return { ok: true, written: [], errors: [], counts, scorecard_file: 's', model: 'm' }
