function inRangePenalty(d: number, band: number | null, bound: number, c: PenaltyCurve): number {
  const width = band ?? c.no_band_width * Math.abs(bound);
  return width > 0 ? c.at_reference_limit * Math.min(d / width, 1) ** c.in_range_exponent : c.at_reference_limit;
