/**
 * The coverage rule, over the markers that score for the person: the present markers left after the redundancy
 * groups, row eligibility and the exclusions. A marker another one replaces, or one that cannot score, counts
 * toward neither minimum and covers no domain.
 */
function validateMarkers(scoring: ReadonlySet<string>, coverage: ScoreSpec["coverage"]): ValidationResult {
  const domainDetails: DomainCoverage[] = [];
  let dc = 0;
  const missing: string[] = [];
  const domains = Object.entries(coverage.domains);

  for (const [dn, dd] of domains) {
    const possible = new Set(dd.markers);
    const present = [...scoring].filter((c) => possible.has(c));
    const covered = present.length >= dd.min_count;
    if (covered) dc++;
    else missing.push(dn);
    domainDetails.push({ domain: dn, description: dd.description, covered, markersPresent: present.sort(), markersPossible: possible });
  }

  const t = scoring.size;
  const ok = t >= coverage.min_markers && dc >= coverage.min_domains;
  let err: string | null = null;
  if (!ok) {
    const parts: string[] = [];
    if (t < coverage.min_markers) parts.push(`Need ${coverage.min_markers}+ markers, got ${t}.`);
    if (dc < coverage.min_domains) parts.push(`Need ${coverage.min_domains}/${domains.length} domains, got ${dc}.`);
    err = parts.join(" ");
  }

  return { valid: ok, totalMarkers: t, domainsCovered: dc, domainsRequired: coverage.min_domains, domainDetails, missingDomains: missing, errorMessage: err };
