/**
 * In each group the first present member that can score for the person (it has a rule: its picked row exists, is
 * eligible and has bounds, and no state excludes it) scores, and every other present member is suppressed by it.
 * A group none of whose present members can score suppresses nothing, and none of them scores.
 */
function resolveRedundancies(
  codes: ReadonlySet<string>,
  rules: ReadonlyMap<string, MarkerRule>,
  groups: readonly ScoreSpecGroup[],
): Record<string, string> {
  const sup: Record<string, string> = {};
  for (const g of groups) {
    const best = g.priority_order.find((c) => codes.has(c) && rules.has(c));
    if (!best) continue;
    for (const c of g.priority_order) {
      if (c !== best && codes.has(c)) sup[c] = best;
    }
  }
  return sup;
}

function assessConfidence(valid: boolean, t1: number, t2: number, dc: number, rule: ScoreSpec["confidence"]): Confidence {
  if (!valid) return rule.below_coverage;
  return rule.levels.find((l) => t1 >= l.min_tier1 && t2 >= l.min_tier2 && dc >= l.min_domains)?.level ?? rule.otherwise;
