function netRatioToLongevityScore(netRatio: number, c: ScoreSpec["score_curve"]): number {
  const raw = c.scale * Math.exp(-c.k * netRatio);
  return Math.max(c.floor, Math.min(c.ceiling, Math.round(raw)));
