  for (const [prefix, state] of LABEL_TO_STATE) {
    if (text === prefix) return { state, ageGroup: "all adults" };
    // A state row with its own age band is labelled with both, as the compile writes it ("Pregnancy 18-39").
    if (text.startsWith(`${prefix} `) && /\\d/.test(text.slice(prefix.length))) return { state, ageGroup: text.slice(prefix.length).trim() };
