 * recognises: such a row belongs to no state the app can know, so the state-aware pick never reads it.
 */
export function rowStateOf(row: ReferenceRowLike): RowStateCode | null {
  const column = typeof row.physiological_state === "string" ? row.physiological_state.toLowerCase().trim() : "";
  if (column) return STATE_CODES.has(column) ? (column as RowStateCode) : null;
