/** Among rows of one state: the person's sex before "both", a numeric band before "All Adults", then the label. */
function firstOf<T extends ReferenceRowLike>(rows: readonly T[], sex: string): T | undefined {
  if (rows.length <= 1) return rows[0];
  const want = sex.toLowerCase();
  const sexRank = (r: T) => (r.sex?.toLowerCase() === want ? 0 : 1);
  const bandRank = (r: T) => (/\\d/.test(r.age_group_en ?? "") ? 0 : 1);
  return [...rows].sort((a, b) => sexRank(a) - sexRank(b) || bandRank(a) - bandRank(b) || (a.age_group_en ?? "").localeCompare(b.age_group_en ?? ""))[0];
}

/**
 * The pick with the lab's state: the first state the person may read (entitledStates) that has a row whose age
 * group contains their age. When no such row contains the age (a minor), the same order runs over the rows whatever
 * their age group, and `ageMatched` is false. A marker whose rows all belong to states the person is not in gets no
 * row: its value is shown with no category (state-rules.md section 5 for the cycle-phase hormones).
 */
function pickForState<T extends ReferenceRowLike>(own: readonly T[], sex: string, age: number, state: RowState): ReferenceRowPick<T> {
  const byState = new Map<RowStateCode, T[]>();
  for (const r of own) {
    const code = rowStateOf(r);
    if (code === null) continue;
    const list = byState.get(code);
    if (list) list.push(r);
    else byState.set(code, [r]);
  }
  const entitled = entitledStates(sex, age, state);
  for (const ageMatched of [true, false]) {
    for (const { code, menopauseFrom } of entitled) {
      const rows = byState.get(code) ?? [];
      const row = firstOf(ageMatched ? rows.filter((r) => rowAgeContains(r, age)) : rows, sex);
      if (row) return { row, ageMatched, menopauseFrom };
