/** One marker's row for a person, and how it was reached. */
export interface ReferenceRowPick<T> {
  row: T | undefined;
  /** False when no age group contained the age and the row is a fallback. */
  ageMatched: boolean;
  /**
   * Set when the row is a menopause row (premenopausal, perimenopausal or postmenopausal): "status" when the
   * recorded status chose it, "age" when none is recorded and age chose it, which the client is told (the fixed
   * note of wording-rules.md section 5). null for every other row, and always without a state.
   */
  menopauseFrom: MenopauseFrom | null;
}

/**
