 *
 * With the lab's `state`, the row is picked by pickForState: state rows only through their state.
 *
 * Without one (null or absent), the rows whose age group contains their age are chosen among by pickReferenceRow;
 * when no age group contains the age (a minor, or a label nothing recognises) the same rule runs over all their
 * rows, so the choice still never depends on database order; `ageMatched` is then false.
 */
export function referenceRowFor<T extends ReferenceRowLike>(
  rows: readonly T[],
  sex: string,
  age: number,
  state?: RowState | null,
): ReferenceRowPick<T> {
  const want = sex.toLowerCase();
  const own = rows.filter((r) => r.sex?.toLowerCase() === want || r.sex?.toLowerCase() === "both");
  if (state != null) return pickForState(own, sex, age, state);
  const row = pickReferenceRow(own.filter((r) => ageGroupContains(r.age_group_en, age)), sex, age);
  return row ? { row, ageMatched: true, menopauseFrom: null } : { row: pickReferenceRow(own, sex, age), ageMatched: false, menopauseFrom: null };
}

/**
 * referenceRowFor for every marker in `rows`, keyed by biomarker_key.
 * `fallbacks` lists the markers whose row did not match the person's age.
 * With a `state`: `menopauseByAge` lists the markers whose row age chose because no menopause status is recorded,
 * and `withoutRow` the markers that have rows for the person's sex, none of them for the state they are in.
 * Both are empty without a state.
 */
export function pickReferenceRows<T extends ReferenceRowLike & { biomarker_key: string }>(
  rows: readonly T[],
  sex: string,
  age: number,
  state?: RowState | null,
): { picked: Map<string, T>; fallbacks: string[]; menopauseByAge: string[]; withoutRow: string[] } {
  const byKey = new Map<string, T[]>();
  for (const r of rows) {
    const list = byKey.get(r.biomarker_key);
    if (list) list.push(r);
    else byKey.set(r.biomarker_key, [r]);
  }
  const want = sex.toLowerCase();
  const picked = new Map<string, T>();
  const fallbacks: string[] = [];
  const menopauseByAge: string[] = [];
  const withoutRow: string[] = [];
  for (const [key, list] of byKey) {
    const { row, ageMatched, menopauseFrom } = referenceRowFor(list, sex, age, state);
    if (!row) {
      if (state != null && list.some((r) => r.sex?.toLowerCase() === want || r.sex?.toLowerCase() === "both")) withoutRow.push(key);
      continue;
    }
    picked.set(key, row);
    if (!ageMatched) fallbacks.push(key);
    if (menopauseFrom === "age") menopauseByAge.push(key);
  }
  return { picked, fallbacks, menopauseByAge, withoutRow };
}
