    const edge = panel("male", 45, (row) => optimalBand(row).find(Number.isFinite) ?? 1);
    const middle = panel("male", 45, (row) => {
      const [lo, hi] = optimalBand(row);
      return Number.isFinite(lo) && Number.isFinite(hi) ? (lo + hi) / 2 : (optimalBand(row).find(Number.isFinite) ?? 1);
    });
