    expect([b.longevityScore, b.totalWeightedPenalty]).toEqual([100, 0]);
    for (const field of ["lsBonusPoints", "totalWeightedBonus", "netWeightedScore"]) expect(field in a, field).toBe(false);
    for (const m of a.markerScores) for (const field of ["rawBonus", "weightedBonus", "bonusEligible", "tier", "tierWeight"]) expect(field in m, field).toBe(false);
    // One in-range result beside eleven optimal ones: the score is the curve of its penalty alone.
    const tg = pickReferenceRows(SEED, "male", 45).picked.get("triglycerides")!; // optimal to 80, reference to 150
    const r = calculateLongevityScoreV2(middle.map((i) => (i.code === "TG" ? { ...i, value: 115 } : i)), "male", 45, SEED);
    const penalty = reviewedPenalty(115, tg) * 2;
    expect(penalty).toBeCloseTo(0.4 * 0.25 * 2, 9);
    expect(r.totalWeightedPenalty).toBeCloseTo(penalty, 4);
    expect(r.netPenaltyRatio).toBeCloseTo(penalty / 25, 4);
