/**
 * The reference change values table (work package WS3-19, ruling D-23), generated and never typed.
 *
 *   npx tsx scripts/governance/build-rcv.ts            writes both files
 *   npx tsx scripts/governance/build-rcv.ts --check    exits 1 when either file differs from the decided rows
 *
 * It reads the `rcv` input of every decided row (docs/signoff/work/decisions/<family>.json, `final_rows`) and writes
 *   docs/signoff/work/rcv.json            the full table, in the shape acceptance check P2 reads, with each row's figures
 *   src/lib/biomarkers/data/rcv.json      the figures alone, for the app (src/lib/biomarkers/trend.ts)
 *
 * The rules, from the ruling:
 *   - Every CVI, CVA and RCV is copied, with its source, from a row. This file computes none and supplies none.
 *   - A row's RCV is complete when the row gives all three figures: a CVI, an analytical CV above zero and the RCV,
 *     and the RCV is the one its own CVI and CVA give (1.96 × √2 × √(CVI² + CVA²), within rounding). An RCV worked
 *     out with a CVA of zero, or given without the two CVs, is not complete.
 *   - A CVA of zero is never written: such a row's CVA is written as null and the row is named.
 *   - A marker has a value only when every one of its rows is complete. Where its rows differ, the largest RCV is the
 *     marker's value, and `largest_rcv_row` names the row it came from. Each row's figures are kept under `rows`.
 *   - A marker without a complete RCV gets none: its `cvi_pct`, `cva_pct` and `rcv_pct` are null, so check P2 fails
 *     on its bands and the app gives no change wording for it. What its rows do hold stays readable under `rows`.
 *   - `placeholder` is true when any row of the marker says so (a stand-in recorded on the row by its family).
 *   - `narrow_band_justification` is the marker's only when every row with a two-sided optimal band carries one;
 *     check P2 reads one justification per marker, so one row's text never covers a sibling row that has none.
 *
 * The output holds no date, so the same rows always give the same bytes.
 */
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";

export const DECISIONS_DIR = "docs/signoff/work/decisions";
export const VERIFY_DIR = "docs/signoff/work/verify";
export const TABLE_FILE = "docs/signoff/work/rcv.json";
export const APP_FILE = "src/lib/biomarkers/data/rcv.json";

/** The largest gap allowed between a row's RCV and the one its own CVI and CVA give (rows round to one decimal). */
export const RCV_ROUNDING_TOLERANCE = 0.15;

export interface RcvInput {
  cvi_pct?: unknown;
  cva_pct?: unknown;
  rcv_pct?: unknown;
  source?: unknown;
  placeholder?: unknown;
  narrow_band_justification?: unknown;
}

export interface DecidedRow {
  marker_key: string;
  sex: string;
  age_group: string;
  physiological_state: string;
  optimal_low?: number | null;
  optimal_high?: number | null;
  rcv?: RcvInput | null;
}

export interface FamilyInput {
  family: string;
  /** Path of the decision file, relative to the repository root. */
  file: string;
  sha256: string;
  /** The decision names the verifier's file it was decided from; false when that file has changed since. */
  verify_file_unchanged: boolean;
  rows: DecidedRow[];
}

export interface RcvRow {
  row_key: string;
  family: string;
  cvi_pct: number | null;
  cva_pct: number | null;
  rcv_pct: number | null;
  placeholder: boolean;
  source: string | null;
  narrow_band_justification: string | null;
  two_sided_optimal_band: boolean;
  complete: boolean;
  /** Why the row's RCV is not complete; empty when it is. */
  missing: string[];
}

export interface RcvMarker {
  cvi_pct: number | null;
  cva_pct: number | null;
  rcv_pct: number | null;
  placeholder: boolean;
  source: string | null;
  narrow_band_justification: string | null;
  complete: boolean;
  /** The row whose RCV, the largest of the marker's rows, is the marker's value; null when the marker has none. */
  largest_rcv_row: string | null;
  missing: string[];
  rows: RcvRow[];
}

export interface RcvTable {
  _generated_by: string;
  _do_not_edit: string;
  _rule: string;
  formula: string;
  inputs: { family: string; file: string; sha256: string; verify_file_unchanged: boolean; rows: number }[];
  counts: { families: number; rows: number; rows_complete: number; markers: number; markers_complete: number; markers_placeholder: number };
  markers: Record<string, RcvMarker>;
}

export interface AppRcvTable {
  _generated_by: string;
  _do_not_edit: string;
  markers: Record<string, { cvi_pct: number | null; cva_pct: number | null; rcv_pct: number | null; placeholder: boolean; complete: boolean }>;
}

const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);
const text = (v: unknown): string | null => (typeof v === "string" && v.trim() ? v : null);

export function rowKeyOf(r: DecidedRow): string {
  return `${r.marker_key}|${r.sex}|${r.age_group}|${r.physiological_state}`;
}

/** One row's figures, copied; whether its RCV is complete, and why not. */
export function rcvRowOf(row: DecidedRow, family: string): RcvRow {
  const input = row.rcv ?? {};
  const cvi = num(input.cvi_pct);
  const cvaGiven = num(input.cva_pct);
  const rcv = num(input.rcv_pct);
  const missing: string[] = [];
  if (row.rcv == null) missing.push("the row has no rcv input");
  if (cvi == null) missing.push("cvi_pct: the row gives no within-subject CV");
  else if (cvi <= 0) missing.push(`cvi_pct: the row gives ${cvi}, which is not a within-subject CV`);
  if (cvaGiven == null) missing.push("cva_pct: the row gives no analytical CV");
  else if (cvaGiven <= 0) missing.push(`cva_pct: the row gives ${cvaGiven}, which is not an analytical CV and is not written`);
  if (rcv == null) missing.push("rcv_pct: the row gives no reference change value");
  else if (rcv <= 0) missing.push(`rcv_pct: the row gives ${rcv}, which is not a reference change value`);
  else if (cvi == null || cvaGiven == null || cvaGiven <= 0) missing.push(`rcv_pct: the row's ${rcv}% does not rest on both a CVI and an analytical CV`);
  else {
    const fromRowFigures = 1.96 * Math.SQRT2 * Math.sqrt(cvi ** 2 + cvaGiven ** 2);
    if (Math.abs(fromRowFigures - rcv) > RCV_ROUNDING_TOLERANCE) {
      missing.push(`rcv_pct: the row's ${rcv}% is not what its CVI ${cvi}% and CVA ${cvaGiven}% give (${fromRowFigures.toFixed(1)}%)`);
    }
  }
  return {
    row_key: rowKeyOf(row),
    family,
    cvi_pct: cvi,
    cva_pct: cvaGiven != null && cvaGiven > 0 ? cvaGiven : null,
    rcv_pct: rcv,
    placeholder: input.placeholder === true,
    source: text(input.source),
    narrow_band_justification: text(input.narrow_band_justification),
    two_sided_optimal_band: row.optimal_low != null && row.optimal_high != null,
    complete: missing.length === 0,
    missing,
  };
}

/** A marker's entry from its rows: the largest complete RCV when every row is complete, else none. */
export function rcvMarkerOf(rows: RcvRow[]): RcvMarker {
  const ordered = [...rows].sort((a, b) => (a.row_key < b.row_key ? -1 : a.row_key > b.row_key ? 1 : 0));
  const incomplete = ordered.filter((r) => !r.complete);
  const placeholder = ordered.some((r) => r.placeholder);
  const banded = ordered.filter((r) => r.two_sided_optimal_band);
  const justified = (banded.length ? banded : ordered).every((r) => r.narrow_band_justification != null);
  const texts = [...new Set((banded.length ? banded : ordered).map((r) => r.narrow_band_justification).filter((t): t is string => t != null))];
  const justification = justified && texts.length ? texts.join("\n") : null;
  if (ordered.length === 0 || incomplete.length > 0) {
    return {
      cvi_pct: null,
      cva_pct: null,
      rcv_pct: null,
      placeholder,
      source: null,
      narrow_band_justification: justification,
      complete: false,
      largest_rcv_row: null,
      missing: incomplete.map((r) => `${r.row_key}: ${r.missing.join("; ")}`),
      rows: ordered,
    };
  }
  // Largest RCV; among equal values, the first row in key order.
  const top = ordered.reduce((best, r) => ((r.rcv_pct as number) > (best.rcv_pct as number) ? r : best), ordered[0]);
  return {
    cvi_pct: top.cvi_pct,
    cva_pct: top.cva_pct,
    rcv_pct: top.rcv_pct,
    placeholder,
    source: top.source,
    narrow_band_justification: justification,
    complete: true,
    largest_rcv_row: top.row_key,
    missing: [],
    rows: ordered,
  };
}

export function buildRcvTable(families: FamilyInput[]): RcvTable {
  const byMarker = new Map<string, RcvRow[]>();
  const seen = new Set<string>();
  let rowCount = 0;
  for (const f of [...families].sort((a, b) => (a.family < b.family ? -1 : 1))) {
    for (const row of f.rows) {
      const r = rcvRowOf(row, f.family);
      if (seen.has(r.row_key)) throw new Error(`${f.file}: row ${r.row_key} is decided twice`);
      seen.add(r.row_key);
      rowCount++;
      byMarker.set(row.marker_key, [...(byMarker.get(row.marker_key) ?? []), r]);
    }
  }
  const markers: Record<string, RcvMarker> = {};
  for (const key of [...byMarker.keys()].sort()) markers[key] = rcvMarkerOf(byMarker.get(key) as RcvRow[]);
  const all = Object.values(markers);
  return {
    _generated_by: "scripts/governance/build-rcv.ts",
    _do_not_edit: "Generated from the rcv input of the decided rows (docs/signoff/work/decisions). Change the rows, then run the generator.",
    _rule:
      "Ruling D-23: every CVI, CVA and RCV is copied with its source from a row; none is computed or supplied here; a CVA of zero is never written. A marker has a value only when every one of its rows gives a CVI, an analytical CV above zero and the RCV those two give; the largest of its rows' RCVs is the marker's value. A marker without a complete RCV has none: check P2 fails on it and the app gives no change wording for it.",
    formula: "RCV% = 1.96 × √2 × √(CVI² + CVA²), two-sided, 95%",
    inputs: [...families]
      .sort((a, b) => (a.family < b.family ? -1 : 1))
      .map((f) => ({ family: f.family, file: f.file, sha256: f.sha256, verify_file_unchanged: f.verify_file_unchanged, rows: f.rows.length })),
    counts: {
      families: families.length,
      rows: rowCount,
      rows_complete: all.reduce((n, m) => n + m.rows.filter((r) => r.complete).length, 0),
      markers: all.length,
      markers_complete: all.filter((m) => m.complete).length,
      markers_placeholder: all.filter((m) => m.placeholder).length,
    },
    markers,
  };
}

/** The app's copy: the figures alone. */
export function appTableOf(table: RcvTable): AppRcvTable {
  const markers: AppRcvTable["markers"] = {};
  for (const [key, m] of Object.entries(table.markers)) {
    markers[key] = { cvi_pct: m.cvi_pct, cva_pct: m.cva_pct, rcv_pct: m.rcv_pct, placeholder: m.placeholder, complete: m.complete };
  }
  return {
    _generated_by: table._generated_by,
    _do_not_edit: `Generated with ${TABLE_FILE} from the decided rows. The sources and each row's figures are in that file.`,
    markers,
  };
}

const sha256 = (file: string): string => createHash("sha256").update(fs.readFileSync(file)).digest("hex");

/** Every decided family, read from disk. */
export function readFamilies(root: string): FamilyInput[] {
  const dir = path.join(root, DECISIONS_DIR);
  const out: FamilyInput[] = [];
  for (const name of fs.readdirSync(dir).filter((n) => n.endsWith(".json")).sort()) {
    const file = path.join(dir, name);
    const doc = JSON.parse(fs.readFileSync(file, "utf8")) as { family?: string; verify_sha256?: string; final_rows?: DecidedRow[] };
    if (!Array.isArray(doc.final_rows)) throw new Error(`${DECISIONS_DIR}/${name}: no final_rows`);
    const verifyFile = path.join(root, VERIFY_DIR, name);
    out.push({
      family: doc.family ?? name.replace(/\.json$/, ""),
      file: `${DECISIONS_DIR}/${name}`,
      sha256: sha256(file),
      verify_file_unchanged: fs.existsSync(verifyFile) && typeof doc.verify_sha256 === "string" && sha256(verifyFile) === doc.verify_sha256,
      rows: doc.final_rows,
    });
  }
  return out;
}

const serialise = (doc: unknown): string => JSON.stringify(doc, null, 2) + "\n";

/** Both files' contents, as the decided rows give them today. */
export function buildRcvFiles(root: string): { table: RcvTable; files: Record<string, string> } {
  const table = buildRcvTable(readFamilies(root));
  return { table, files: { [TABLE_FILE]: serialise(table), [APP_FILE]: serialise(appTableOf(table)) } };
}

function main(): void {
  const root = process.cwd();
  const check = process.argv.includes("--check");
  const { table, files } = buildRcvFiles(root);
  const c = table.counts;
  const summary = `${c.markers_complete} of ${c.markers} markers have a complete reference change value (${c.rows_complete} of ${c.rows} rows, ${c.families} families); ${c.markers_placeholder} markers carry a placeholder flag`;
  if (check) {
    const stale = Object.entries(files).filter(([file, content]) => !fs.existsSync(path.join(root, file)) || fs.readFileSync(path.join(root, file), "utf8") !== content);
    if (stale.length) {
      console.error(`build-rcv --check: ${stale.map(([f]) => f).join(" and ")} differ${stale.length === 1 ? "s" : ""} from the decided rows. Run: npx tsx scripts/governance/build-rcv.ts`);
      process.exit(1);
    }
    console.log(`build-rcv --check: both files match the decided rows. ${summary}`);
    return;
  }
  for (const [file, content] of Object.entries(files)) {
    fs.mkdirSync(path.dirname(path.join(root, file)), { recursive: true });
    fs.writeFileSync(path.join(root, file), content);
    console.log(`wrote ${file}`);
  }
  console.log(summary);
}

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(__filename)) main();
