import fs from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { NO_APPRECIABLE_CHANGE, referenceChangeValue, trendBetween, type RcvMarkers, type TrendResult } from "./trend";
import { EVA_LABORATORY_SOURCES } from "./biological-age-v3-adapter";
import {
  APP_FILE,
  buildRcvFiles,
