const MARKERS: RcvMarkers = {
  with_rcv: { cvi_pct: 4.4, cva_pct: 1.1, rcv_pct: 12.6, placeholder: false, complete: true },
  stand_in: { cvi_pct: 8.6, cva_pct: 2, rcv_pct: 24.5, placeholder: true, complete: true },
