    expect(v.kind).toBe("no_appreciable_change");
    if (v.kind !== "no_appreciable_change") return;
    expect(v.change_pct).toBeCloseTo(10, 6);
    expect(v.rcv_pct).toBe(12.6);
    expect(v.sentence).toEqual(NO_APPRECIABLE_CHANGE);
