/**
 * The route's time limit. A confirm stores the values and then writes the summary, which takes most of the time;
 * the limit is stated so that a request's longest life is known (confirm-claim.ts reads the age of the stored
 * values against it). The literal must equal CONFIRM_MAX_DURATION_SECONDS.
 */
export const maxDuration = 300;

/** The status of a lab as extraction leaves it: the lab_results.status column's default (extract/route.ts sets none). */
const EXTRACTED_STATUS = "processing";
/** The status this route leaves when an attempt fails with an exception (the catch below). */
const FAILED_STATUS = "error";
const READY_STATUS = "ready";
/** The source extraction gives the lab it creates, and the one this route gives it when it takes it. */
const EXTRACTED_SOURCE = "upload";
const CONFIRMED_SOURCE = "user_upload";
const UPLOAD_SOURCES: readonly string[] = [EXTRACTED_SOURCE, CONFIRMED_SOURCE];

/**
 * What a confirm does with a lab the client owns, by the lab's state. Only an upload's lab is ever touched: one
 * created by the upload's extraction (source "upload") or already taken by this route ("user_upload").
 *
 *   status      source        stored values   the confirm
 *   processing  upload        none            first confirm: takes the lab (see below), stores, completes
 *   error       either        none            retry after an attempt that threw before it stored: the same
 *   processing  user_upload   none            another request has taken the lab: 409 in_progress
 *   error       either        some            resumed: the values stay as stored, the rest is completed
 *   processing  either        some, old       resumed: the request that stored them was cut off
 *   processing  either        some, recent    the request that stored them may be running: 409 in_progress
 *   ready       either        any             answered as a success, nothing written
 *
 * Every other lab (one waiting for its context, one from EVA's laboratory or an administrator, one with an unknown
 * status) is refused with a 409 and its reason before anything is written: confirming into it would overwrite its
 * status, source, panel type, collection date and context snapshot and add a second set of values to it.
 *
 * Taking the lab is a single conditional update that names the state the request read, with the row returned:
 * "processing/upload" to "processing/user_upload" for a first confirm, "error" to "processing" for a retry. Of two
 * requests that read the same state only one gets the row back; the other is answered 409 in_progress and has
 * written nothing. A request that gives the lab up without storing anything puts its state back.
 *
 * A resumed confirm never processes or stores the request's results: the stored values are the report. It
 * recomputes the lab's figures from them, writes the summary and the action steps again (the steps are deleted and
 * written anew), and finishes as a first confirm does. The lab becomes ready by a conditional update as well, and
 * only the request that made it ready counts the upload and sends the email.
 */
type ConfirmRefusal = "status_ready" | "status_pending_context" | "status_unknown" | "not_an_upload" | typeof IN_PROGRESS;

function stateBeforeValues(lab: { status?: unknown; source?: unknown }): ConfirmRefusal | "ready" | null {
  const upload = UPLOAD_SOURCES.includes(lab.source as string);
  if (lab.status === READY_STATUS) return upload ? "ready" : "status_ready";
  if (lab.status !== EXTRACTED_STATUS && lab.status !== FAILED_STATUS) {
    return lab.status === "pending_context" ? "status_pending_context" : "status_unknown";
  }
  return upload ? null : "not_an_upload";
}

/** A step that failed with nothing to tell the client but its code: the answer carries no sentence. */
class ConfirmStepError extends Error {
  constructor(readonly code: string, cause?: unknown) {
    super(code);
    this.cause = cause;
  }
}

type ShownFigures = ProcessingResult["biologicalAge"];

export async function POST(req: NextRequest) {
  const supabase = await createClient();
  let labResultId: string | null = null;

  try {
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Validate request body with Zod
    const rawBody = await req.json().catch(() => null);
    const parseResult = ConfirmBodySchema.safeParse(rawBody);
    if (!parseResult.success) {
      return NextResponse.json(
        { error: "Invalid request body", details: parseResult.error.issues },
        { status: 400 }
      );
    }
    const {
      labResultId: lrId,
      biomarkers,
      collectionDate,
      contextVersionId,
      transientContext,
    } = parseResult.data;

    // 1. Get profile
    const profile = await getUserProfile(user.id);
    if (!profile) {
      return NextResponse.json({ error: "Profile not found" }, { status: 404 });
    }

    // Require DOB and sex before processing
    if (!profile.date_of_birth || !profile.sex) {
      return NextResponse.json(
        { error: "Please complete your profile (date of birth and sex) before confirming lab results." },
        { status: 400 }
      );
    }

    const isSubscriber = profile.subscription_status === "active";
    const totalUsed = ((profile as unknown as Record<string, unknown>).total_uploads_used as number) ?? 0;

    // Verify lab_result belongs to user
    const { data: labResult, error: labError } = await supabase
      .from("lab_results")
      .select("id, user_id, status, source")
      .eq("id", lrId)
      .eq("user_id", user.id)
      .single();

    if (labError || !labResult) {
      return NextResponse.json({ error: "Lab result not found" }, { status: 404 });
    }

    // What this confirm does is decided by the lab's state (the table above stateBeforeValues). A lab that cannot
    // be confirmed is refused here with a 409 and its reason, before anything is written or removed, and its
    // status is not touched by the catch below either. When the lab's stored values cannot be read, nothing is
    // written and the answer is a 500: the request can be sent again.
    const statusBefore = (labResult as { status?: unknown }).status as string;
    const sourceBefore = (labResult as { source?: unknown }).source as string;
    const refuse = (reason: ConfirmRefusal) => {
      console.warn(`[confirm] Lab ${lrId} refused: ${reason} (status ${JSON.stringify(statusBefore)})`);
      return NextResponse.json({ code: NOT_AWAITING_CONFIRM, reason }, { status: 409 });
    };
    const notChecked = (error: unknown) => {
      console.error(`[confirm] Lab ${lrId}: its stored values could not be checked:`, error);
      return NextResponse.json({ code: "lab_state_not_checked" }, { status: 500 });
    };
    const before = stateBeforeValues(labResult as { status?: unknown; source?: unknown });
    if (before && before !== "ready") return refuse(before);

    // The results that cannot be used are set aside (decision D-24): each is named in the answer and logged, and
    // only the others go on. Nothing is stored by this.
    const screened = screenSubmittedResults(biomarkers);
    const setAside: SetAsideResult[] = [...screened.setAside];

    /** When each stored value of the lab was stored, or null when they cannot be read. */
    const storedTimes = async (): Promise<unknown[] | null> => {
      const { data, error } = await supabase.from("biomarker_values").select("created_at").eq("lab_result_id", lrId);
      if (error || !Array.isArray(data)) {
        console.error(`[confirm] Lab ${lrId}: its stored values could not be read:`, error);
        return null;
      }
      return data.map((row) => (row as { created_at?: unknown }).created_at);
    };

    /** The lab's figures as they are stored, in the shape a first confirm answers with. */
    const storedFigures = async (): Promise<ShownFigures> => {
      const { data, error } = await supabase
        .from("lab_results")
        .select("biological_age, longevity_score, longevity_grade")
        .eq("id", lrId)
        .maybeSingle();
      if (error || !data) {
        console.error(`[confirm] Lab ${lrId}: its figures could not be read:`, error);
        return null;
      }
      const row = data as { biological_age?: unknown; longevity_score?: unknown; longevity_grade?: unknown };
      const age = row.biological_age == null ? null : Number(row.biological_age);
      const score = row.longevity_score == null ? null : Number(row.longevity_score);
      if (age === null && score === null) return null;
      const years = calculateAge(profile.date_of_birth as string);
      return {
        biologicalAge: age,
        delta: age !== null && Number.isFinite(years) ? age - years : null,
        longevityScore: score,
        lsGrade: typeof row.longevity_grade === "string" ? row.longevity_grade : null,
