     */
    const finish = async (stored: number, figures: ShownFigures) => {
      const { data: made, error: readyError } = await supabase
        .from("lab_results")
        .update({ status: READY_STATUS })
        .eq("id", lrId)
        .in("status", [EXTRACTED_STATUS, FAILED_STATUS])
        .select("id");
      if (readyError) {
        console.error("[confirm] Failed to set ready status:", readyError);
        throw new ConfirmStepError("lab_not_marked_ready", readyError);
      }
