      await recomputeAndCacheUserBA(user.id, supabase).catch((err) =>
        console.error("[confirm] recomputeAndCacheUserBA failed:", err),
      );

      // Increment upload count
      const { error: counterError } = await supabase
        .from("profiles")
        .update({ total_uploads_used: totalUsed + 1 })
        .eq("id", user.id);
      if (counterError) {
        console.error("[confirm] Failed to increment upload counter:", counterError);
      }

      // Send results-ready email (fire-and-forget)
      const firstName = profile.full_name?.split(" ")[0] ?? "";
      const locale = profile.locale ?? "en";
      sendEmail(
        user.email ?? "",
        "results-ready",
        {
          firstName,
          biomarkerCount: stored,
          biologicalAge: figures?.biologicalAge ?? null,
          baDelta: figures?.delta ?? null,
          longevityScore: figures?.longevityScore ?? null,
          locale,
        },
        locale
      ).catch((err) => {
        console.error("[confirm] Email send failed:", err);
      });
