    return NextResponse.json({
      labResultId,
      processed: result.processed.length,
      unmatched: result.unmatched.length,
      biologicalAge: result.biologicalAge,
      calculatedMetrics: result.calculatedMetrics.length,
      // Each result that was not used, with its reason code: the upload screen shows the sentence of
      // wording-rules.md section 7 for it, in the client's language.
      setAside,
    });
