      }
    }

    // A step of this route that failed is answered by its code, with no sentence.
    if (e instanceof ConfirmStepError) return NextResponse.json({ code: e.code }, { status: 500 });
    const message = e instanceof Error ? e.message : "Failed to process";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}
