 * Fail closed:
 *   - The state cannot be read, or the marker has no stored value: the pick runs without a state, over the rows
 *     that need no declaration (rows for pregnancy, lactation, hormone therapy and oral contraception, and rows
 *     whose label nothing recognises, are left out first, so no path reaches them).
 *   - No row is picked (the marker's rows all belong to states the person is not in): the page keeps the marker's
 *     names, panel and flags, which belong to the marker, and shows no clinical note and no bounds.
 *   - The rows cannot be read: no reference at all, as before.
 *
 * A laboratory's own eGFR keeps its value-only treatment (lab-reported.ts shownAsValueOnly).
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import { loadLabState } from "@/lib/patient-context/physiological-state";
import { shownAsValueOnly } from "./lab-reported";
import { referenceRowFor, rowStateOf, type ReferenceRowLike, type RowState, type RowStateCode } from "./reference-row";
import { calculateAge } from "./zone-classifier";

/** What the page reads of a biomarker_references row. */
export interface DetailReferenceRow extends ReferenceRowLike {
  biomarker_key: string;
  name_en: string;
  name_es: string;
  optimal_low: number | null;
  optimal_high: number | null;
  normal_low: number | null;
  normal_high: number | null;
  clinical_notes_en: string | null;
  clinical_notes_es: string | null;
  is_genetic: boolean;
  is_base_panel: boolean;
  panel_category: string;
}

/** The states a person is in only by declaring them: without a state, their rows are never read. */
const DECLARED_ONLY: ReadonlySet<RowStateCode> = new Set<RowStateCode>(["pregnancy", "lactation", "hormone_therapy", "oral_contraception"]);

/** Whether a row may be read by someone whose state is not known. */
function readableWithoutState(row: ReferenceRowLike): boolean {
  const code = rowStateOf(row);
  return code !== null && !DECLARED_ONLY.has(code);
}

/**
 * The row whose text the page shows, among one marker's rows. `state` is the lab's physiological state, or null
 * when there is none to read or it could not be read.
 *
 * When no row applies, the marker's names, panel and flags are kept (from a row chosen by a fixed order, never the
 * database's: a row for no state first, then the person's sex, then the label) with no clinical note and no bounds.
 * Null when the marker has no row for the person's sex.
 */
export function pickDetailReference<T extends DetailReferenceRow>(
  rows: readonly T[],
  sex: string,
  age: number,
  state: RowState | null,
): T | null {
  const want = sex.toLowerCase();
  const own = rows.filter((r) => r.sex?.toLowerCase() === want || r.sex?.toLowerCase() === "both");
  if (own.length === 0) return null;

  const picked = state != null ? referenceRowFor(own, sex, age, state).row : referenceRowFor(own.filter(readableWithoutState), sex, age).row;
  if (picked) return picked;

  const stateRank = (r: T) => (rowStateOf(r) === "none" ? 0 : 1);
  const sexRank = (r: T) => (r.sex?.toLowerCase() === want ? 0 : 1);
  const identity = [...own].sort(
    (a, b) => stateRank(a) - stateRank(b) || sexRank(a) - sexRank(b) || (a.age_group_en ?? "").localeCompare(b.age_group_en ?? ""),
  )[0];
  return {
    ...identity,
    optimal_low: null,
    optimal_high: null,
    normal_low: null,
    normal_high: null,
    clinical_notes_en: null,
    clinical_notes_es: null,
  };
}

/**
 * Reads the marker's rows and the state of the lab the page leads with, and returns the row to show
 * (pickDetailReference). `leadLabResultId` is the lab of the most recent stored value of the marker; null when the
 * person has none. The age is today's, as processing picks (zone-classifier.ts calculateAge).
 */
export async function loadDetailReference(
  supabase: SupabaseClient,
  person: { userId: string; sex: string | null | undefined; dateOfBirth: string | null | undefined },
  biomarkerKey: string,
  leadLabResultId: string | null | undefined,
): Promise<DetailReferenceRow | null> {
  const sex = person.sex?.toLowerCase() ?? "both";
  const age = person.dateOfBirth ? calculateAge(person.dateOfBirth) : NaN;

  const { data: rows, error } = await supabase
    .from("biomarker_references")
    .select("*")
    .eq("biomarker_key", biomarkerKey)
    .in("sex", [sex, "both"]);
  if (error || !Array.isArray(rows) || rows.length === 0) return null;

  let state: RowState | null = null;
  if (leadLabResultId) {
    try {
      state = (await loadLabState(supabase, person.userId, leadLabResultId)).state;
    } catch (e) {
      console.error(`[biomarker detail] the state of lab ${leadLabResultId} could not be read; the reference row is picked without one:`, e);
    }
  }

  const reference = pickDetailReference(rows as DetailReferenceRow[], sex, age, state);
  return reference ? shownAsValueOnly(reference) : null;
}
