  const element = (await BiomarkerDetailPage({ params: Promise.resolve({ locale: "en", key }) })) as { props: Record<string, unknown> };
  return element.props as {
    locale: string;
    biomarkerKey: string;
    latest: Record<string, unknown> | null;
    historicalValues: Record<string, unknown>[];
    reference: Record<string, unknown> | null;
    wearable: unknown[];
  };
}

// The pregnancy row first, as the database might return it.
const FERRITIN_ROWS = [reference("ferritin", "female", "Pregnancy"), reference("ferritin", "female", "Lactation"), reference("ferritin", "female", "All Adults")];

beforeEach(() => {
  state.profile = { id: "u1", sex: "female", date_of_birth: `${new Date().getFullYear() - 35}-01-01` };
});

describe("the biomarker detail page", () => {
  it("does not show the pregnancy row to a person who has not declared pregnancy, though the database returns it first", async () => {
    database({ values: [value("ferritin", LAB_OLD, 60)], references: FERRITIN_ROWS });
    const props = await shown();
    expect(props.reference).toEqual(FERRITIN_ROWS[2]);
  });

  it("shows the pregnancy row when the lab of the latest value declares pregnancy, and reads that lab's state", async () => {
    const calls = database({ values: [value("ferritin", LAB_OLD, 60), value("ferritin", LAB_NEW, 35)], references: [...FERRITIN_ROWS].reverse(), pregnantLabs: [LAB_NEW] });
    const props = await shown();
    expect(props.reference?.clinical_notes_en).toBe("notes: Pregnancy");
    const labReads = calls.filter((c) => c.table === "lab_results");
    expect(labReads).toHaveLength(1);
    expect(labReads[0].ops.find((o) => o.op === "eq" && o.args[0] === "id")?.args[1]).toBe(LAB_NEW);
  });

  it("an earlier lab's pregnancy does not reach the page once a later value is stored", async () => {
    database({ values: [value("ferritin", LAB_OLD, 35), value("ferritin", LAB_NEW, 60)], references: FERRITIN_ROWS, pregnantLabs: [LAB_OLD] });
    expect((await shown()).reference?.clinical_notes_en).toBe("notes: All Adults");
  });

  it("shows the ordinary row in pregnancy where the family has no pregnancy row", async () => {
    const ordinary = [reference("ferritin", "female", "All Adults")];
    database({ values: [value("ferritin", LAB_NEW, 35)], references: ordinary, pregnantLabs: [LAB_NEW] });
    expect((await shown()).reference).toEqual(ordinary[0]);
  });

  it("a failed state read picks without a state", async () => {
    const logged = vi.spyOn(console, "error").mockImplementation(() => undefined);
    database({ values: [value("ferritin", LAB_NEW, 35)], references: FERRITIN_ROWS, pregnantLabs: [LAB_NEW], labRead: { error: { message: "timeout" } } });
    expect((await shown()).reference?.clinical_notes_en).toBe("notes: All Adults");
    expect(logged).toHaveBeenCalledTimes(1);
    logged.mockRestore();
  });

  it("shows no clinical note, and the marker's names, when every row belongs to a state the person is not in", async () => {
    database({ values: [value("ferritin", LAB_OLD, 60)], references: FERRITIN_ROWS.slice(0, 2) });
    expect((await shown()).reference).toMatchObject({ name_en: "Ferritin", name_es: "Ferritina", panel_category: "nutrients", clinical_notes_en: null, clinical_notes_es: null });
  });

  it("hands the screen the stored values, the latest one and the wearable data as before", async () => {
    const values = [value("ferritin", LAB_OLD, 60), value("ferritin", LAB_NEW, 35)];
    const calls = database({ values, references: FERRITIN_ROWS });
    const props = await shown();
    expect(props.locale).toBe("en");
    expect(props.biomarkerKey).toBe("ferritin");
    expect(props.historicalValues).toEqual(values);
    expect(props.latest).toEqual(values[1]);
    expect(props.wearable).toEqual([{ date: "2026-10-01", hrv: 55 }]);
    const read = calls.find((c) => c.table === "biomarker_values")!;
    expect(read.ops.map((o) => [o.op, ...o.args])).toEqual([
      ["select", "*, lab_results!inner(user_id, collection_date, source)"],
      ["eq", "biomarker_key", "ferritin"],
      ["eq", "lab_results.user_id", "u1"],
      ["order", "created_at", { ascending: true }],
    ]);
  });

  it("a marker with no stored value shows its ordinary row and reads no lab", async () => {
    const calls = database({ values: [], references: FERRITIN_ROWS });
    const props = await shown();
    expect(props.latest).toBeNull();
    expect(props.historicalValues).toEqual([]);
    expect(props.reference).toEqual(FERRITIN_ROWS[2]);
    expect(calls.some((c) => c.table === "lab_results")).toBe(false);
  });

  it("a laboratory's own eGFR stays a value only: no category or interval on its values, no bounds from the reference row", async () => {
    const egfrRows = [reference("egfr_creatinine_based", "both", "All Adults")];
    database({ values: [value("egfr_creatinine_based", LAB_NEW, 88)], references: egfrRows });
    const props = await shown("egfr_creatinine_based");
    expect(props.latest).toMatchObject({ value: 88, zone: "unclassified", optimal_low: null, optimal_high: null, normal_low: null, normal_high: null });
    expect(props.reference).toMatchObject({ name_en: "Ferritin", clinical_notes_en: "notes: All Adults", optimal_low: null, optimal_high: null, normal_low: null, normal_high: null });
  });

  it("sends a visitor who is not signed in to the login page before any read", async () => {
    const calls = database({ user: null, values: [value("ferritin", LAB_OLD, 60)], references: FERRITIN_ROWS });
    await expect(shown()).rejects.toThrow("redirect:/en/login");
    expect(calls).toHaveLength(0);
  });
});
