import { CONFIRM_LEASE_MS, confirmUntilSettled } from "@/lib/lab-results/confirm-claim";

const LAB = "11111111-1111-4111-8111-111111111111";
const CLIENT = "22222222-2222-4222-8222-222222222222";
const VERSION = "33333333-3333-4333-8333-333333333333";

const db = vi.hoisted(() => ({
  lab: null as null | Record<string, unknown>,
  values: [] as Array<{ id: string; lab_result_id: string; created_at: string }>,
  uploadsUsed: 0,
  writesSent: [] as string[],
  changes: [] as string[],
  inserts: 0,
  steps: [] as string[],
  /** returns an error response for a call, or a promise to delay it */
  fail: null as null | ((c: { table: string; chain: string; call: FakeCall }) => boolean),
  gate: null as null | ((c: { table: string; chain: string; call: FakeCall }) => Promise<void> | null),
}));

function matches(row: Record<string, unknown>, c: FakeCall): boolean {
  return c.ops.every((o) => {
    if (o.op === "eq") return row[o.args[0] as string] === o.args[1];
    if (o.op === "in") return (o.args[1] as unknown[]).includes(row[o.args[0] as string]);
    return true;
  });
}
function respond(c: FakeCall) {
  const chain = ops(c);
  if (db.fail?.({ table: c.table, chain, call: c })) return { data: null, error: { message: "connection reset" } };
  const write = /^(insert|update|upsert|delete)/.test(chain);
  if (write) db.writesSent.push(`${c.table}:${chain}`);
  if (c.table === "lab_results") {
    const hit = db.lab && matches(db.lab, c) ? db.lab : null;
    if (chain.startsWith("update")) {
      if (!hit) return { data: [] };
      const patch = argsOf(c, "update")?.[0] as Record<string, unknown>;
      Object.assign(hit, patch);
      db.changes.push(JSON.stringify(patch));
      return { data: [{ id: hit.id }] };
    }
    if (chain.startsWith("delete")) { if (hit) { db.lab = null; db.values = []; db.changes.push("delete"); } return { data: null }; }
    return { data: hit ? { ...hit } : null, error: hit ? null : { message: "no rows" } };
  }
  if (c.table === "biomarker_values") {
    const rows = db.values.filter((v) => matches(v, c));
    const limit = argsOf(c, "limit")?.[0] as number | undefined;
    return { data: limit === undefined ? rows : rows.slice(0, limit) };
  }
  if (c.table === "profiles" && chain.startsWith("update")) { db.uploadsUsed = (argsOf(c, "update")?.[0] as { total_uploads_used: number }).total_uploads_used; return { data: null }; }
  if (c.table === "biomarker_references") { const [, keys] = (argsOf(c, "in") ?? []) as [string?, string[]?]; return { data: (keys ?? []).map((biomarker_key) => ({ biomarker_key })) }; }
  if (c.table === "patient_context_versions") return { data: { id: VERSION } };
  return { data: null };
}

