export interface RowCounts {
  decided_rows: number;
  by_verifier_class: Record<string, number>;
  rows_that_score: number;
  rows_that_wait: number;
  rows_listed_and_not_scored: number;
  rows_not_listed: number;
  rows_listed: number;
  verifier_rows: number;
  verifier_rows_without_decided_row: number;
}

/**
 * Every decided row accounted for once: it scores, it waits, it is listed and does not score, or it is a row of
 * classes b to e that is counted and not listed. The generator stops when the four do not add up to the total.
 */
function rowCounts(inp: GeneratorInputs, rows: Map<string, RowReport[]>, listed: ReadonlySet<string>): RowCounts {
  const all = [...rows.values()].flat();
  const decided = inp.families.reduce((n, f) => n + f.decided.length, 0);
  const byClass: Record<string, number> = {};
  for (const r of all) byClass[r.class ?? "none"] = (byClass[r.class ?? "none"] ?? 0) + 1;
  const counts: RowCounts = {
    decided_rows: decided,
    by_verifier_class: Object.fromEntries(Object.keys(byClass).sort().map((c) => [c, byClass[c]])),
    rows_that_score: all.filter((r) => r.scores).length,
    rows_that_wait: all.filter((r) => !r.scores && isWaiting(r)).length,
    rows_listed_and_not_scored: all.filter((r) => !r.scores && !isWaiting(r) && listed.has(r.row)).length,
    rows_not_listed: all.filter((r) => !r.scores && !isWaiting(r) && !listed.has(r.row)).length,
    rows_listed: all.filter((r) => listed.has(r.row)).length,
    verifier_rows: inp.families.reduce((n, f) => n + (f.verified?.length ?? 0), 0),
    verifier_rows_without_decided_row: verifierRowsWithoutDecidedRow(inp).length,
  };
  const sum = counts.rows_that_score + counts.rows_that_wait + counts.rows_listed_and_not_scored + counts.rows_not_listed;
  const classSum = Object.values(counts.by_verifier_class).reduce((a, b) => a + b, 0);
  if (sum !== decided || classSum !== decided || all.length !== decided) {
    fail(`the row counts do not add up: ${decided} decided rows, ${all.length} reported, ${sum} by status, ${classSum} by class`);
  }
  const unlistedA = all.filter((r) => !listed.has(r.row) && r.class === inp.spec.eligibility.marker_class);
  if (unlistedA.length) fail(`class ${inp.spec.eligibility.marker_class} rows are not listed: ${unlistedA.map((r) => r.row).join(", ")}`);
  return counts;
}

export interface DroppedVerifierRow {
  family: string;
  row: string;
  source: string;
  class: string | null;
  grade: string | null;
  state: string;
  reason: string;
}

/** The verifier's rows that have no decided row, in family and row order. */
function verifierRowsWithoutDecidedRow(inp: GeneratorInputs): DroppedVerifierRow[] {
  const out: DroppedVerifierRow[] = [];
  for (const fam of [...inp.families].sort((a, b) => a.family.localeCompare(b.family))) {
    const decided = new Set(fam.decided.map(rowId));
    (fam.verified ?? []).forEach((row, index) => {
      if (decided.has(rowId(row))) return;
      out.push({
        family: fam.family,
        row: rowId(row),
        source: `verify/${fam.family}.json final_rows[${index}]`,
        class: row.marker_class ?? null,
        grade: row.grade ?? null,
        state: stateOf(row),
        reason: "the decision has no row for it: nothing is compiled, nothing can score",
      });
    });
  }
  return out;
}

