// ─── The rows the exclusion is read on: this draw and the client's other results within the window ───

/** HbA1c, haemoglobin, ferritin and eGFR from another result count when drawn within this many days of this draw. */
export const HBA1C_WINDOW_DAYS = 90;

/** Statuses of another result whose values count: processed, whether or not the client has confirmed the context. */
export const OTHER_RESULT_STATUSES: readonly string[] = ["ready", "pending_context"];

/** The keys read from the client's other results: HbA1c, and what its exclusions need. */
export const OTHER_RESULT_KEYS: readonly string[] = ["hba1c", "hemoglobin", "ferritin", "egfr_creatinine_based", "egfr"];

/** Another lab result of the same client, with its rows of OTHER_RESULT_KEYS. */
export interface OtherResult<Row extends GlycationRow = GlycationRow> {
  id: string;
  /** lab_results.collection_date (YYYY-MM-DD); null when unknown. */
  collection_date: string | null;
  created_at?: string | null;
  values: readonly Row[];
}

/** "YYYY-MM-DD" (a Postgres date, or the start of a timestamp) as [year, month, day]; null when not a real date. */
export function isoDateParts(s: unknown): [number, number, number] | null {
  if (typeof s !== "string") return null;
  const m = /^(\\d{4})-(\\d{2})-(\\d{2})/.exec(s.trim());
  if (!m) return null;
  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];
  const t = new Date(Date.UTC(y, mo - 1, d));
  if (t.getUTCFullYear() !== y || t.getUTCMonth() !== mo - 1 || t.getUTCDate() !== d) return null;
  return [y, mo, d];
}

/** Calendar day number of a date, for differences in whole days. */
function dayNumber([y, mo, d]: [number, number, number]): number {
  return Date.UTC(y, mo - 1, d) / 86_400_000;
}

/** `date` ("YYYY-MM-DD") moved by `days` calendar days, as "YYYY-MM-DD". */
export function shiftIsoDate(date: string, days: number): string {
  const parts = isoDateParts(date);
  if (!parts) throw new Error(`not a date: ${date}`);
  return new Date((dayNumber(parts) + days) * 86_400_000).toISOString().slice(0, 10);
}

/** A lab's draw date as the window reads it: lab_results.collection_date as "YYYY-MM-DD"; null when it is no date. */
export function drawDateOf(collectionDate: unknown): string | null {
  return isoDateParts(collectionDate) ? (collectionDate as string).trim().slice(0, 10) : null;
}

/** The client's other results drawn within HBA1C_WINDOW_DAYS of the draw, the closest to it first. */
export function recentOtherResults<Row extends GlycationRow>(others: readonly OtherResult<Row>[], drawDate: string | null): OtherResult<Row>[] {
  const draw = isoDateParts(drawDate);
  if (!draw) return [];
  const drawDay = dayNumber(draw);
  const dated = others.flatMap((o) => {
    const parts = isoDateParts(o.collection_date);
    if (!parts || Math.abs(dayNumber(parts) - drawDay) > HBA1C_WINDOW_DAYS) return [];
    return [{ o, day: dayNumber(parts) }];
  });
  // Closest draw first, before or after; at equal distance the one stored last, then the id, so the choice never
  // depends on read order.
  dated.sort(
    (a, b) =>
      Math.abs(a.day - drawDay) - Math.abs(b.day - drawDay) ||
      (b.o.created_at ?? "").localeCompare(a.o.created_at ?? "") ||
      b.o.id.localeCompare(a.o.id),
  );
  return dated.map((d) => d.o);
}

/**
 * The rows the exclusion is read on for one draw: the draw's own rows, then the rows of the client's other results
 * drawn within the window. Without a draw date no other result is read: the draw's own rows only. The biological
 * age and the score both call glycationExclusion on exactly this set (ruling D-06).
 */
export function glycationRows<Row extends GlycationRow>(own: readonly Row[], others: readonly OtherResult<Row>[], drawDate: string | null): Row[] {
  return [...own, ...recentOtherResults(others, drawDate).flatMap((o) => o.values)];
}
